        'intros' => [
            'custom_fields' => 'Opbyg de ekstra oplysninger, en slags sag har brug for - fx en startdato og et brugernavn på en ny medarbejder - og vælg, hvilke sagstyper hvert felt er på. Hvert felt afgør selv, om det skal udfyldes, når en sag oprettes, når den lukkes eller begge dele, og om anmelderen bliver spurgt om det på portalen.',
            'checklists' => 'En tjekliste kan markere trin som obligatoriske. Dette afgør, hvad der sker, hvis nogen lukker en sag, før de trin er afkrydset.',
            'mandatory_fields' => 'Vælg, hvilke sagsfelter der skal udfyldes, før en sag lukkes, og hvad der sker, når nogen lukker en med et af dem tomt. Reglen gælder overalt, hvor en sag kan lukkes: sagsskærmen, bulk-handlinger, REST API\'et og arbejdsgange.',
            'departments' => 'Afdelinger grupperer og dirigerer sager til det rette område af din organisation — opret dem, din service desk bruger til at kategorisere og fordele arbejde.',
            'teams' => 'Teams bestemmer, hvilke afdelinger medarbejdere har adgang til. Tildel afdelinger til teams, og tildel derefter medarbejdere til teams for at styre deres adgang.',
            'ticket_types' => 'Sagstyper klassificerer, hvad en henvendelse er (f.eks. hændelse, serviceanmodning) — definér de typer, medarbejdere kan sætte på en sag.',
            'ticket_origins' => 'Sagskilder registrerer, hvordan en sag kom ind (f.eks. e-mail, telefon, portal) — definér de kilder, medarbejdere kan vælge mellem.',
            'mailboxes' => 'Postkasser forbinder FreeITSM til e-mailkonti, så indgående beskeder bliver til sager, og svar går tilbage ud — tilføj og godkend dem, din service desk overvåger.',
            'privacy' => 'En sag rummer ikke kun din samtale med den person, der oprettede den. At videresende til en leverandør eller cc\'e en kollega lægger den besked på samme sag — og deres svar lander der også. Dette afgør, hvor meget af det anmelderen ser i selvbetjeningsportalen.',
            'indexing' => 'Teksten i vedhæftede filer læses, så den kan søges frem. Word-, Excel-, PowerPoint- og almindelige tekstfiler læses af FreeITSM selv, i det øjeblik de ankommer. PDF\'er, ældre Office-filer og scannede dokumenter kræver en separat dokumentlæsningstjeneste — sæt den op under <strong>System &rarr; Integrationer &rarr; Apache Tika</strong> — og fordi de tager langt længere tid, læses de i baggrunden. Disse to indstillinger afgør, hvornår det baggrundsarbejde sker.',
            'merge_behaviour' => 'Når to sager viser sig at være den samme ting, kan en medarbejder flette dem. Disse indstillinger afgør, hvad det gør ved de sagsreferencer, dine anmeldere sidder med, og hvad der sker med samtalerne. De gælder for alle — en fletning ændrer, hvad kunden ser, så to medarbejdere på samme postkasse må ikke kunne være uenige om det.',
            'reply_templates' => 'Færdige svar, dine medarbejdere kan sætte ind i et svar i stedet for at skrive dem igen. Dette er de delte, som hele teamet ser — en medarbejders egne private skabeloner gemmes fra svarvinduet og vises ikke her.',
            'rota_shifts' => 'Vagter er de arbejdsmønster-skabeloner (f.eks. tidlig, sen, tilkald), medarbejdere tildeles på personalets vagtplan — definér dem her, før du bygger vagtplanen.',
            'analysts' => 'Medarbejdere er de ansatte, der logger ind og arbejder med sager — tilføj dem, nulstil adgangskoder, og tildel dem til teams for at styre deres adgang.',
            'general' => 'Generelle indstillinger styrer, hvordan sager opfører sig - genåbning, udsættelse og hvor længe beskeder og tråde vises.',
            'statuses' => 'Arbejdsgangstilstande, en sag kan være i. Statusser markeret som <em>Lukket</em> tæller som afsluttede — bruges af rapporter, vagttårnstællere og den automatiske lukket-dato ved tildeling. Præcis én status er standard for nye sager.',
            'priorities' => 'Prioritetsbånd vist på sager. Præcis én prioritet er standard for nye sager.',
            'rota_locations' => 'Hvor hver medarbejder arbejder på en given dag — bruges af personalets vagtplan og vises som et farvet mærke på hver post. Præcis én lokation er standard for nye vagtplan-poster.',
            'email_templates' => 'Automatiske e-mailsvar udløst af sagshændelser. Kun den første aktive skabelon pr. begivenhed bruges.',
        ],
        'messaging' => [
            'channels_heading' => 'Beskedkanaler',
            'channels_intro' => 'Lad kunder chatte med en medarbejder over WhatsApp — hver besked bliver til en sag, ligesom e-mail. Tilføj en kanal nedenfor, og indsæt så dens <strong>webhook-URL</strong> hos din udbyder (Twilio eller Meta), så indgående beskeder når denne installation.',
            'base_url_label' => '<strong>Offentlig base-URL</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (eller din ngrok-adresse under test)',
            'base_url_help' => 'Adressen, udbydere bruger til at nå denne installation. Sæt den, og webhook-URL\'erne nedenfor bliver klar til at kopiere. Lad stå tomt for at bruge den adresse, du browser fra. Tester du lokalt? Kør <code>ngrok http 80</code> og indsæt <code>https://…ngrok-free.dev</code>-adressen, den udskriver.',
            'templates_heading' => 'Beskedskabeloner',
            'templates_intro' => 'Forhåndsgodkendte skabeloner lader en medarbejder svare <strong>efter det 24-timers vindue er lukket</strong>. WhatsApp tillader kun fri tekst inden for 24 timer efter kundens seneste besked; udover det kan kun en skabelon, Meta/Twilio har godkendt, sendes. Opret &amp; godkend skabelonen hos din udbyder, og tilføj så dens definition her (med <code>{{1}}</code>, <code>{{2}}</code>-pladsholdere), så medarbejdere kan vælge og udfylde den.',
        ],
        'webchat' => [
            'heading' => 'Webchat-widgets',
            'intro' => 'Sæt et chatvindue på et websted — en besøgende skriver en besked, den bliver til en sag, og medarbejdere svarer fra indbakken ligesom enhver anden kanal. Tilføj en widget nedenfor, og indsæt så dens indlejringskode på webstedet.',
            'col_key' => 'Widget-nøgle',
            'col_origins' => 'Websted(er)',
            'any_origin' => 'Alle (ikke begrænset)',
            'add_title' => 'Tilføj webchat-widget',
            'edit_title' => 'Redigér webchat-widget',
            'name' => 'Navn',
            'name_placeholder' => 'f.eks. Acme websted',
            'company' => 'Virksomhed',
            'company_help' => 'Fastgør enhver samtale fra denne widget til én virksomhed. Lad stå ikke sat på en installation med kun én virksomhed.',
            'greeting' => 'Velkomst',
            'greeting_placeholder' => 'Hej! Hvordan kan vi hjælpe?',
            'accent' => 'Accentfarve',
            'launcher' => 'Tekst på åbneknap',
            'launcher_placeholder' => 'Chat med os',
            'origins' => 'Tilladte websted(er)',
            'origins_help' => 'Ét domæne pr. linje (f.eks. https://acme.com). Kun disse websteder må vise widgeten. Lad stå tomt for at tillade alle websteder (kun til test).',
            'offline' => 'Offlinebesked',
            'offline_placeholder' => 'Vi er ikke tilgængelige lige nu — læg din besked, og vi mailer dig tilbage.',
            'require_email' => 'Bed besøgende om navn og e-mail, før de chatter',
            'active' => 'Aktiv',
            'embed_label' => 'Indlejringskode',
            'embed_help' => 'Indsæt denne lige før den afsluttende &lt;/body&gt;-tag på hver side, der skal vise chatvinduet.',
            'embed_after_save' => 'Indlejringskoden vises her, når du har gemt widgeten.',
            'avail_heading' => 'Tilgængelighed',
            'business_hours' => 'Åbningstider',
            'always_open' => 'Altid åben',
            'business_hours_help' => 'Uden for disse tider viser widgeten din offlinebesked og optager stadig henvendelsen som en sag, der besvares senere. Kalendere håndteres under SLA-indstillinger.',
            'email_heading' => 'E-mail',
            'email_when_away' => 'Send svar til den besøgende pr. e-mail, hvis de har forladt chatten',
            'email_when_away_help' => 'Hvis en medarbejder svarer, mens den besøgende ikke længere følger med i chatten, sendes svaret til den e-mail, de opgav.',
            'ai_heading' => 'AI-svar',
            'ai_enabled' => 'Svar fra videnbasen med AI',
