        'oauth' => [
            'success_title' => 'Godkendelse gennemført!',
            'success_body' => 'Postkassen er nu forbundet og klar til at tjekke for e-mails.',
            'mismatch_title' => 'Forkert konto logget ind',
            'mismatch_body' => 'Du er logget ind med en anden konto end målpostkassen, så dette ville læse den forkerte indbakke. Log ind igen som målpostkassen, eller skift denne postkasse til app-only-godkendelse.',
