        'sla' => [
            'heading' => 'SLA-aftaler',
            'intro' => 'SLA\'er der tager højde for åbningstider, med mål for svar og løsning pr. prioritet. Uret sættes på pause ved statusser markeret "Sætter SLA på pause" på <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">fanen Statusser</a>. Se <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">designnotater</a>.',
            'global_heading' => 'Globale indstillinger',
            'enforce_from' => 'Håndhæv SLA\'er fra',
            'enforce_from_help' => 'Lad feltet stå tomt for at <strong>deaktivere SLA-håndhævelse helt</strong>. Angiv en dato og et klokkeslæt, og kun sager oprettet på eller efter dette tidspunkt bliver evalueret &mdash; nyttigt til at undtage eksisterende sager, når du aktiverer SLA\'er for første gang.',
            'priority_change_label' => 'Når en sags prioritet ændres undervejs',
            'priority_change_forward' => 'Anvend den nye SLA fra ændringstidspunktet og frem',
            'priority_change_recompute' => 'Genberegn med tilbagevirkende kraft ud fra det nye mål',
            'priority_change_reset' => 'Nulstil SLA-uret helt',
            'reopen_label' => 'Når en lukket sag genåbnes',
            'reopen_reset' => 'Start SLA\'en forfra',
            'reopen_continue' => 'Fortsæt hvor uret blev sat på pause',
            'first_response_label' => 'Første svar tæller som',
            'first_response_outbound' => 'Kun udgående e-mail (Svar / Videresend)',
            'first_response_status' => 'Statusskift væk fra standarden',
            'first_response_either' => 'Begge dele, alt efter hvad der sker først',
            'warning_threshold' => 'Advarselstærskel (%)',
            'warning_threshold_help' => 'Sager markeres visuelt i indbakken, når denne % af deres SLA er forløbet.',
            'notifications_label' => 'Notifikationer',
            'notify_assignee' => 'Send e-mail til den tildelte medarbejder ved advarselstærsklen',
            'notify_lead' => 'Send e-mail til teamlederen ved overskridelse',
            'save_global' => 'Gem globale indstillinger',
            'targets_heading' => 'SLA-mål pr. prioritet',
            'targets_intro' => 'Svar- og løsningstider for hver sagsprioritet. Tider angives i minutter (60 = 1 time, 240 = 4 timer, 1440 = 1 dag). Kalenderen afgør, hvilke åbningstider uret tæller ud fra. Lad feltet stå tomt for at springe det mål over.',
            'col_priority' => 'Prioritet',
            'col_response_mins' => 'Svar (min.)',
            'col_resolution_mins' => 'Løsning (min.)',
            'col_calendar' => 'Kalender',
            'col_save' => 'Gem',
            'calendars_heading' => 'Åbningstidskalendere',
            'calendars_intro' => 'Definér arbejdstider, tidszoner og lister over fridage. Kalendere anvendes af SLA-målene (ovenfor) og af de enkelte prioriteter. Én kalender er standard for nye prioriteter.',
            'col_name' => 'Navn',
            'col_timezone' => 'Tidszone',
            'col_hours' => 'Timer',
            'col_holidays' => 'Fridage',
            'col_default' => 'Standard',
            'col_actions' => 'Handlinger',
            'notifs_heading' => 'Notifikationer ved overskridelse',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Sådan fungerer notifikationsregler</strong>Hver regel har fire dele: et <strong>omfang</strong>, en <strong>udløser</strong>, et <strong>mål</strong> og en liste over <strong>modtagere</strong>.<br><br><strong>Omfang</strong> kan enten være <em>Standard</em> (reglen gælder for sager i alle afdelinger) eller en <em>specifik afdeling</em> (reglen gælder kun for sager i den afdeling).<br>Når en sag evalueres, leder systemet først efter en regel, der matcher dens afdeling &mdash; hvis der findes én, vinder den regel, og standarden ignoreres. Hvis der ikke er nogen afdelingsspecifik regel, bruges standardreglen. På den måde kan du sætte fornuftige standarder, der dækker alle afdelinger, og derefter lave undtagelser, hvor ét team har andre eskaleringsbehov.<br><br><strong>Udløser</strong> er enten <em>Advarsel</em> (sagen har krydset advarselstærsklen &mdash; en mulig overskridelse nærmer sig) eller <em>Overskridelse</em> (sagen har nu overskredet sit SLA-mål &mdash; en reel overskridelse). Hver er sin egen regel, så du kan give besked til forskellige personer ved advarsler og overskridelser.<br><br><strong>Mål</strong> er, hvilket SLA-ur der overvåges &mdash; <em>Svar</em>, <em>Løsning</em> eller <em>Begge</em>.<br><br><strong>Modtagere</strong> kan være en hvilken som helst kombination af: sagens nuværende tildelte medarbejder, alle medarbejdere i sagens afdelingsteams, én navngiven medarbejder, og/eller en liste af frit angivne e-mailadresser (nyttigt til fælles indbakker eller Slack/Teams e-mail-broer).<br><br><strong style="color:var(--warning-text, #92400e);">Ingen regler = ingen e-mails.</strong> Selv hvis en sag overskrider sit mål, sker der intet, før du tilføjer mindst én regel (start med et Standard-omfang Advarsel + Overskridelse-par for at få dækning for alt).',
            'notifs_dedup' => 'Hver sag sender højst én e-mail pr. mål pr. udløser &mdash; cron-jobbet holder styr på, hvad der allerede er sendt, så du ikke får dubletter.',
            'col_scope' => 'Omfang',
            'col_trigger' => 'Udløser',
            'col_target' => 'Mål',
            'col_recipients' => 'Modtagere',
            'col_active' => 'Aktiv',
            'notifs_cron_note' => 'Cron-jobbet, der sender disse e-mails, findes i <code>cron/sla_breach_check.php</code>. Se <code>docs/sla-cron-setup.md</code> for opsætning af Jobplanlægning i Windows + cron i Linux.',
            'cron_heading' => 'Cron-aktivitet',
            'cron_refresh' => 'Opdatér',
            'cron_intro' => 'De seneste <span id="slaCronRunsLimit">20</span> kørsler af overskridelses-cron\'en (CLI og HTTP). Inkluderer afviste forespørgsler (rate-limited, godkendelse mislykkedes), så den samme kilde til sandheden understøtter både rate-limit-tjek og sikkerhedsrevisioner. Ryddes automatisk efter <strong><span id="slaCronRetentionDays">30</span> dage</strong>; mindste interval mellem vellykkede kørsler er <strong><span id="slaCronMinInterval">30</span>s</strong> (begge kan konfigureres i <code>system_settings</code>).',
            'col_when' => 'Hvornår',
            'col_source' => 'Kilde',
            'col_duration' => 'Varighed',
            'col_sent' => 'Sendt',
            'col_skipped' => 'Sprunget over',
            'col_errors' => 'Fejl',
            'col_outcome' => 'Resultat',
        ],
        'dept_confidential' => [
            'label' => 'Sager her er fortrolige',
            'help' => 'Hver sag i denne afdeling, eller flyttet ind i den, markeres som Fortrolig og holdes dermed skjult for anmelderens ledere. Når du slår dette til, markeres også de sager, der allerede er her. Når du slår det fra, ændres ingen sag - gør en Normal igen på selve sagen.',
            'chip' => 'Fortrolig',
