            'help' => 'Til en postkasse som HR. Hver sag, der ankommer hertil, markeres som Fortrolig i det øjeblik, den lander, før nogen har læst den, og holdes dermed skjult for anmelderens ledere.',
        ],
        'pauses_sla' => [
            'label' => 'Sætter SLA-uret på pause',
            'help' => 'Når en sag har denne status, stopper SLA-uret med at tælle. Bruges til statusser, hvor der ikke arbejdes aktivt på sagen (f.eks. <em>På hold</em>, <em>Afventer svar</em>).',
        ],
        'rota_weekends' => 'Inkludér weekender på vagtplanen',
        'numbering' => [
            'heading' => 'Sagsnummerering',
            'intro' => 'Hver sag får en reference. Det er det, folk læser op i telefonen, skriver på en formular og søger efter seks måneder senere, så det er værd, at det er noget, man kan sige højt. Du vælger formen her.',
            'style' => 'Sådan laves numrene',
            'style_sequential' => 'Optælling',
            'style_sequential_help' => 'TICKET-000001, TICKET-000002 og så videre. Nemt at sige, nemt at genkende, og rækkefølgen fortæller dig, hvad der kom først.',
            'style_random' => 'Tilfældig',
            'style_random_help' => 'Tre bogstaver og otte cifre, som CKQ-418-73926. Det er, hvad FreeITSM altid har gjort. Ingen kan gætte, hvor mange sager du har, men ingen kan heller læse en op.',
            'format' => 'Sådan ser et nummer ud',
            'format_help' => 'Sæt <code>{######}</code> dér, hvor cifrene skal stå &mdash; ét nummertegn pr. ciffer. Alt andet bevares, som du skriver det. Du kan også bruge <code>{YYYY}</code> eller <code>{YY}</code> for året, <code>{MM}</code> og <code>{DD}</code>, samt <code>{TYPE}</code> eller <code>{COMPANY}</code> for en kort kode fra sagstypen eller virksomheden. For eksempel <code>INC-{YYYY}-{#####}</code>.',
            'preview_label' => 'De næste ville se sådan ud',
            'start' => 'Start optælling fra',
            'start_help' => 'Nyttigt hvis du flytter fra et andet system og vil fortsætte, hvor det slap.',
            'scope' => 'Tæl separat for',
            'scope_global' => 'Én talrække til det hele',
            'scope_per_type' => 'Hver sagstype',
            'scope_per_company' => 'Hver virksomhed',
            'scope_help' => 'At tælle pr. sagstype giver hændelser og anmodninger deres egne talrækker, hvilket er den måde, de fleste store service desks gør det på. Hvis du tæller separat, skal formatet angive, hvad der er hvad — sæt {TYPE} eller {COMPANY} ind i det, ellers ville alle grupper give de samme numre.',
            'reset' => 'Start forfra',
            'reset_never' => 'Aldrig — bliv ved med at tælle',
            'reset_yearly' => 'Hvert år',
            'reset_monthly' => 'Hver måned',
            'reset_help' => 'Kun nyttigt hvis år eller måned er en del af nummeret, ellers får du dubletter. Kombinér med noget i stil med <code>INC-{YYYY}-{#####}</code>.',
            'existing_note' => '<strong>Intet, der allerede er nummereret, ændres.</strong> Eksisterende sager beholder den reference, de har, og enhver reference, FreeITSM nogensinde har udstedt, bliver ved med at virke &mdash; også i svar på gamle e-mails. Hvis du også vil have eksisterende sager omnummereret, er der et værktøj til det nedenfor. <strong>Du løber ikke tør for cifre:</strong> den bredde, du vælger, er et minimum, så sag nummer 1.000.001 bare bliver ét ciffer længere i stedet for at gå i stykker.',
            'saved' => 'Sagsnummerering gemt.',
            'renumber_heading' => 'Omnummerér eksisterende sager',
            'renumber_intro' => 'Omskriver referencen på alle eksisterende sager til ovenstående skema, ældste først. Mest nyttigt lige efter at have skiftet fra et andet system, når du vil have, at alt ser ensartet ud.',
            'renumber_safety' => '<strong>Gamle referencer bliver ved med at virke.</strong> Ethvert nummer, en sag nogensinde har haft, huskes, så et svar på en e-mail, der citerer det gamle, stadig havner på den rigtige sag &mdash; ligesom når sager flettes. Et udgået nummer bliver heller aldrig givet til en anden sag. Det her kan du dog ikke fortryde, så se på forhåndsvisningen først.',
            'renumber_preview' => 'Forhåndsvisning',
            'renumber_go' => 'Omnummerér',
            'renumber_preview_first' => 'Forhåndsvis først — knappen bliver aktiv, når du har set, hvad det ville gøre.',
            'renumber_preview_heading' => 'Kun forhåndsvisning &mdash; intet er blevet ændret.',
            'renumber_done_heading' => 'Sager omnummereret.',
            'renumber_summary' => '{changing} af {total} sag(er) ville blive omnummereret. {skipped} matcher allerede.',
            'renumber_next_after' => 'Den næste nye sag ville blive {number}.',
            'renumber_confirm_title' => 'Omnummerér alle sager?',
            'renumber_confirm' => 'Dette omskriver referencen på alle eksisterende sager.

Gamle referencer bliver ved med at virke, så svar på gamle e-mails stadig finder den rigtige sag. Men de numre, folk har skrevet ned, sat på formularer og gemt i deres egne regneark, vil ikke længere være dem, der vises i FreeITSM.

Dette kan ikke fortrydes. Vil du fortsætte?',
        ],
        'general' => [
            'system_name' => 'Systemnavn',
            'system_name_moved' => 'Systemnavnet - den første del af hver sidetitel - angives i {link}, fordi det gælder for alle moduler.',
            'system_name_moved_link' => 'System -> Branding',
            'system_name_placeholder' => 'f.eks. Service Desk sagssystem',
            'system_name_help' => 'Vises i begyndelsen af hver sidetitel - navnet i browserfanen og i bogmærker. Tomt betyder "Service Desk".',
            'reopen_label' => 'Genåbning',
            'reopen_toggle' => 'Genåbn en lukket sag, når anmelderen svarer',
            'snooze_hour_label' => 'Start på arbejdsdagen',
            'snooze_hour_help' => 'Tidspunktet, hvor en sag, der er udsat til "I morgen" eller "Næste uge", kommer tilbage. Læses i hver medarbejders egen tidszone, så en service desk spredt over flere tidszoner hver får deres egen morgen.',
            'collapse_heading' => 'Lange beskeder',
            'collapse_desc' => 'Lange e-mails begraver det, du åbnede sagen for at læse. Beskeder, der er højere end grænsen, forkortes med et Vis mere-link. Intet slettes — hele beskeden er altid ét tryk væk.',
            'collapse_enabled_label' => 'Forkort lange beskeder',
            'collapse_lines_label' => 'Forkort beskeder, der er højere end ca.',
            'collapse_lines_help' => 'linjer. En besked lige over grænsen får lov at være, så linket ikke dukker op for to ords skyld.',
            'collapse_newest_label' => 'Vis altid den nyeste besked fuldt ud',
            'collapse_newest_help' => 'Den besked, du kom for at læse, forkortes aldrig.',
            'collapse_quoted_label' => 'Forkort citeret historik',
            'collapse_quoted_help' => 'Et kort svar med en lang citeret tråd under sig er kort efter enhver linjetælling og stadig ulæseligt, så citeret historik forkortes separat.',
            'collapse_remember_label' => 'Husk hvad jeg har åbnet',
            'collapse_remember_help' => 'Beskeder, du folder ud, forbliver foldet ud på denne enhed.',
            'group_older_label' => 'Fold ældre beskeder sammen',
            'group_older_help' => 'Ud over antallet nedenfor foldes ældre beskeder sammen til én linje, du kan åbne.',
            'group_show_label' => 'Hold så mange nye beskeder åbne',
            'flag_duplicates_label' => 'Gør opmærksom på beskeder der er ankommet før',
            'flag_duplicates_help' => 'En gensendelse, en dobbelt levering eller en returmail foldes sammen med en note. Intet slettes.',
            'team_folders_heading' => 'Teammapper',
            'team_folders_label' => 'Medarbejdere ser',
            'team_folders_all' => 'Alle teams',
            'team_folders_mine' => 'Kun de teams, de tilhører',
            'team_folders_help' => 'Ændrer kun mappelisten - ingen mister overblikket over en sag. Et team med sager, en medarbejder kan se, vises stadig, så mapperne fortsat stemmer. Administratorer ser altid alle teams.',
            'watch_heading' => 'Følg sager',
            'watch_help' => 'Hvad en sags følgere får besked om. Hver følgers egne notifikationsindstillinger gælder stadig oven i.',
            'watch_inactive_label' => 'Når en følger deaktiveres',
            'watch_inactive_stop' => 'Hold op med at give dem besked - behold deres følgninger, hvis de vender tilbage',
            'watch_inactive_remove' => 'Fjern dem fra alle sager, de følger',
            'watch_inactive_help' => 'En deaktiveret medarbejder får aldrig besked om noget. Hold op skjuler deres følgninger og sætter dem tilbage, hvis medarbejderen aktiveres igen; Fjern sletter dem, når medarbejderen deaktiveres. Fjernelse gælder fra det tidspunkt, dette gemmes.',
            'watch_event_ticket_reply_received' => 'Anmelderen svarer',
            'watch_event_ticket_note_added' => 'Der tilføjes en note',
            'watch_event_ticket_status_changed' => 'Status ændres',
            'watch_event_ticket_priority_changed' => 'Prioriteten ændres',
            'watch_event_ticket_assigned' => 'Sagen tildeles en anden',
            'watch_event_sla_warning' => 'Den nærmer sig sit SLA-mål',
            'watch_event_sla_breached' => 'Den overskrider sit SLA-mål',
            'ai_heading' => 'AI reading aids',
            'ai_desc' => 'Optional, and off until you turn them on: unlike everything else on this page these use your own AI provider and cost money per use. The provider, model and API key are configured once on the Reply cleanup tab. Nothing an AI writes ever replaces the ticket — the conversation stays exactly where it is, in full.',
            'ai_summary_label' => 'Keep a short AI summary at the top of each ticket',
            'ai_summary_help' => 'A few lines saying where the ticket stands, written on request and kept up to date. It always shows when it was written, how much it read, and how far the conversation has moved on since. Every version is kept, so a worse summary never destroys a better one.',
            'ai_auto_label' => 'Refresh it automatically after this many new messages',
            'ai_auto_help' => '0 means never — the Refresh button is then the only way, and nothing is ever charged without somebody asking. A refresh only happens when an analyst opens the ticket, so a busy queue nobody is reading costs nothing.',
            'ai_max_label' => 'Messages to read',
            'ai_max_help' => 'How far back a summary reads. A longer ticket is read from its most recent end, and the summary says so rather than describing a beginning it never saw.',
            'ai_notes_label' => 'Let it read internal notes',
            'ai_notes_help' => 'Internal notes often hold what was actually tried. They are staff-only either way — the summary is never shown to a requester — but turn this off if notes on your desk hold things that should not leave it.',
            'ai_read_label' => 'Tilbyd "Læs den" på en sag',
            'ai_confidential_label' => 'Fortrolige sager og AI',
            'ai_confidential_block' => 'Send dem aldrig til AI (anbefalet)',
            'ai_confidential_allow' => 'Behandl dem som enhver anden sag',
            'ai_confidential_help' => 'Dækker alle AI-funktioner, der læser en sag: resuméet, Læs den, oprydning af svar, Spørg AI, sammenfletningsresuméer, vidensartikler, kanalresuméer, problemanalyse og krisecenter-botten. En fortrolig sag sendes enten ikke, eller - hvor mange sager læses på én gang - udelades eller vises kun med nummer.',
            'ai_read_help' => 'A button that reads the whole ticket and briefs you on it: what happened, what is unresolved, and what it would do next. Asked for and read once, stored nowhere.',
            'reopen_help' => 'Gælder, uanset hvor anmelderen kommer tilbage — selvbetjeningsportalen, et svar på din notifikations-e-mail, WhatsApp eller webchat. Sagen vender tilbage til din første åbne status. Kun sager i en status markeret som lukket påvirkes (angiv, hvilke det er, under Statusser).',
        ],
        'privacy' => [
            'third_party_label' => 'Beskeder sendt til andre end anmelderen',
            'opt_hide' => 'Skjul dem for anmelderen',
            'opt_hide_help' => 'Beskeden og dens vedhæftede filer vises slet ikke i anmelderens portal. Anbefalet: de fleste går ud fra, at det er privat at videresende en sag til en leverandør.',
            'opt_no_attachments' => 'Vis beskeden, men ikke dens vedhæftede filer',
            'opt_no_attachments_help' => 'Anmelderen kan se, at du har kontaktet nogen andre, og hvad der blev skrevet, men kan ikke downloade nogen vedhæftede filer.',
            'opt_show' => 'Vis alt',
            'opt_show_help' => 'Anmelderen ser hele sagen på nøjagtig samme måde som dine medarbejdere, inklusive videresendelser og svar fra tredjeparter. Sådan opførte systemet sig, før denne indstilling fandtes.',
            'always_visible_note' => '<strong>Altid synligt for anmelderen:</strong> deres egne beskeder og ethvert svar rettet til dem. <strong>Aldrig synligt:</strong> interne noter — de er skjult for portalen uanset denne indstilling. Beskeder på WhatsApp og webchat vises altid, fordi de samtaler per definition foregår mellem anmelderen og din service desk.',
            'timezone' => 'Tidszone',
            'timezone_help' => 'Bruges til at vise datoer og klokkeslæt i hele systemet.',
        ],
        'reply_cleanup' => [
            'intro1' => 'Når en medarbejder skriver et groft udkast til et svar i sagens svar-vindue, omskriver knappen <strong>✨ Oprydning</strong> det til en ordentligt formateret e-mail — tilføjer en hilsen som "Kære [name]," retter grammatik, anvender den tone, du vælger nedenfor, og afslutter med "Med venlig hilsen,". Den vil <strong>ikke</strong> opfinde tekniske detaljer eller udvande indholdet.',
            'intro2' => 'Denne funktion bruger sin egen Anthropic API-nøgle (adskilt fra RFP AI og Knowledge AI), så dens forbrug vises som en separat linje på Anthropics faktureringsdashboard.',
            'tone' => 'Tone',
            'tone_friendly' => 'Venlig (standard)',
            'tone_formal' => 'Formel',
            'tone_brief' => 'Kortfattet',
            'tone_help' => 'Anvendes på hver oprydning, medmindre den ændres her.',
            'custom_label' => 'Brugerdefinerede instruktioner <span style="color: #999; font-weight: normal;">(valgfrit)</span>',
            'custom_placeholder' => 'f.eks. Afslut altid med \'Mange tak,\'&#10;Omtal virksomheden som \'BillCorp\'&#10;Brug britisk engelsk stavemåde konsekvent',
            'custom_help' => 'Føjes til systemprompten vist til højre. Brug dette til organisationsspecifikke justeringer (variationer i afslutningshilsen, firmanavn, sprogpræferencer). De faste sikkerhedsregler og outputformatet har stadig forrang.',
            'prompt_summary' => 'Vis systemprompt (skrivebeskyttet)',
            'prompt_panel_intro' => 'Dette er den fulde systemprompt, der sendes til Claude ved hver oprydning. Navnet i hilsenen varierer fra sag til sag; tonen afspejler dit valg til venstre. Dine brugerdefinerede instruktioner (hvis nogen) føjes til i slutningen ved kørsel — de vises ikke her, rediger dem i tekstfeltet til venstre.',
        ],
        'csat_tab' => [
            'intro1' => 'Når en sag lukkes, sendes en kort spørgeskema-e-mail til anmelderen, hvor de bedes vurdere oplevelsen 1&ndash;5. Svar registreres på den medarbejder, der lukkede sagen, så du kan trække CSAT-tendenser pr. medarbejder, og vises som et widget på dashboardet.',
            'intro2' => 'Spørgeskema-e-mailen konfigureres under <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">E-mailskabeloner</a> &mdash; opret en skabelon med hændelsen <strong>CSAT-undersøgelse</strong>, og indsæt <code>[csat_link]</code> i brødteksten for at indsætte URL\'en til den engangsvurdering.',
            'mode_off' => 'Fra',
            'mode_off_help' => 'Der sendes ingen spørgeskema-e-mails.',
            'mode_auto' => 'Automatisk ved lukning',
            'mode_auto_help' => 'Et spørgeskema sendes automatisk, når en sag skifter til en lukket status.',
            'mode_manual' => 'Kun manuelt',
            'mode_manual_help' => 'Medarbejdere klikker på <em>Feedback</em> i sagens værktøjslinje, når de vil spørge.',
            'delay_help' => 'Vent så mange minutter efter lukning, før der sendes. <code>0</code> = med det samme. Nyttigt hvis du vil have brugeren til at bekræfte, at løsningen faktisk holdt, inden de bliver bedt om at vurdere den.',
            'reminder' => 'Send én påmindelse, hvis undersøgelsen ikke besvares',
            'reminder_hours' => 'Påmind efter (timer)',
            'reminder_help' => 'Højst én påmindelse, på e-mail, med samme link - så begge e-mails virker, og kun én bedømmelse gemmes. Kun undersøgelser sendt på e-mail får en påmindelse, uanset om de blev sendt ved lukning eller fra knappen <strong>Feedback</strong>. Sendes ikke, hvis sagen er åben igen eller i papirkurven, når påmindelsen forfalder. Bruger e-mailskabelonen <strong>CSAT-påmindelse</strong>, hvis du har en, ellers undersøgelsesskabelonen igen. Sendes af baggrundsjobbet <em>Forsinkede tilfredshedsundersøgelser og påmindelser</em>. Når du slår dette til, påmindes ingen om gamle undersøgelser: kun dem, hvis påmindelse forfalder fra nu af.',
            'one_per_ticket' => 'Ét spørgeskema pr. sag',
            'one_per_ticket_help' => 'Hvis slået til, får en sag, der genåbnes og lukkes igen, kun endnu et spørgeskema, når en medarbejder udløser det manuelt &mdash; forhindrer spørgeskema-spam på en ustabil sag.',
            'in_channel' => 'Spørg chatkunder i deres chat',
            'in_channel_help' => 'En kunde, der skrev ind via WhatsApp, Telegram, Slack, Teams eller Mattermost, bliver spurgt i den chat &mdash; med knapper, hvor appen har dem, og &ldquo;svar 1 til 5&rdquo;, hvor den ikke har &mdash; i stedet for via e-mail. WhatsApp kun så længe dens 24-timersvindue er åbent; ellers, og hvis en chatbesked mislykkes, bruges e-mailundersøgelsen.',
            'scale_stars' => 'Stjerner',
            'scale_emojis' => 'Emojis',
            'scale_help' => 'Begge muligheder gemmer det samme tal fra 1&ndash;5, så dashboards og gennemsnit fungerer ens uanset hvad &mdash; det ændrer kun, hvordan selve spørgeskemasiden ser ud.',
        ],
        'analyst_extra' => [
