            'signin_local' => 'Lokal (brugernavn &amp; adgangskode)',
            'signin_help' => 'Lokale brugere logger ind med en adgangskode. Tildel en udbyder for at kræve SSO for denne medarbejder — ved deres næste SSO-login knyttes deres identitet automatisk (matchet på e-mail).',
            'access_all' => 'Adgang til alle virksomheder',
