    'help' => [
        'case' => [
            'nav' => 'Sagsrapporter',
            'heading' => 'Sagsrapporter',
            'intro' => 'Når en gennemgang eller en revisor spørger, hvordan en sag blev håndteret, samler <strong>Eksportér</strong> sagen, dens samtale og de opgaver, der udførte arbejdet, i ét printbart dokument - så ingen skal kopiere det ud i hånden.',
            'step1' => '<strong>Åbn sagen</strong> og vælg <strong>Eksportér</strong> i dens værktøjslinje (under <strong>Mere</strong>, når læseruden er smal). Rapporten åbner i en ny fane. For en opgave uden sag bruger du i stedet dokumentknappen øverst i opgavevinduet.',
            'step2' => '<strong>Markér, hvad der skal med</strong> i panelet til venstre. Rapporten tegnes om, mens du markerer, og intet registreres, mens du vælger.',
            'step3' => '<strong>Vælg layout</strong>: en forside, en indholdsfortegnelse, hvert afsnit på en ny side og et sidehoved med sidetal.',
            'step4' => '<strong>Udskriv</strong>, og vælg derefter <em>Gem som PDF</em> i udskriftsdialogen. Fjern markeringen ved browserens egne <em>Sidehoveder og sidefødder</em> - rapporten udskriver sine egne.',
            'contents' => '<strong>Hvad der kommer med:</strong> et overblik over sagen (med dens brugerdefinerede felter, tilknyttede aktiver, konfigurationselementer og relaterede sager); hver besked, ældste først; noterne; sagens tjeklister; hver tilknyttet opgave med dens delopgaver, tjeklisteresultater og undtagelsesnoter, formularsvar, de fulgte procedurer, opfølgninger og kommentarer; historikken for sagen og for hver opgave; og et indeks over dokumenterne og e-mailens vedhæftede filer, med det fingeraftryk, FreeITSM registrerede for hvert dokument.',
            'layout' => '<strong>Layout:</strong> indholdsfortegnelsen viser hvert afsnit og hver opgave, og hver post er et link i den gemte PDF. Sidehoved og sidetal (<em>Side 3 af 12</em>) kræver en aktuel Chrome eller Edge; andre browsere udskriver rapporten uden dem.',
            'who' => '<strong>Hvem ser hvad:</strong> rapporten viser kun det, du kunne se på skærmen. Opgaver, aktiver, konfigurationselementer, relaterede sager, dokumenter og formularsvar kontrolleres hver for sig med deres egen regel, og alt, du ikke må se, bliver <em>talt</em> - aldrig navngivet - så læseren ved, at noget er udeladt. <strong>Interne noter udelades, medmindre du markerer dem med</strong>, fordi en rapport som regel forlader teamet.',
            'recorded' => '<strong>Hvad der registreres:</strong> udskrivning skriver en linje <em>Sagsrapport</em> i sagens revisionsspor med, hvem der udskrev den, og hvilke afsnit den dækkede. Forhåndsvisning og ændring af valgene registrerer intet.',
            'note' => 'En sagsrapport er en kopi af optegnelsen, ikke en fremstilling: intet omformuleres eller opsummeres, billeder i e-mails gengives ikke, filer vises på en liste i stedet for at blive medtaget, og kun historik, som FreeITSM faktisk har registreret, vises. Et afsnit, der ikke kan læses, siger det med rødt i stedet for at se tomt ud.',
        ],
        'workspace' => [
            'nav' => 'Arbejdsområde og sagstabel',
            'heading' => 'Arbejdsområdet og sagstabellen',
            'intro' => 'To andre måder at arbejde sig gennem sager på, begge valgfrie. <strong>Arbejdsområdet</strong> sætter én sag op til at arbejde i frem for at læse. <strong>Sagstabellen</strong> viser listen over sager som en tabel, du kan filtrere, sortere og gemme.',
            'ws_title' => 'Arbejdsområdet',
            'ws_what' => 'I arbejdsområdet sidder sagens egenskaber i en kolonne til venstre, og dens <strong>Samtale</strong>, <strong>Arbejde</strong> (tjeklister, formularer og tilknyttede opgaver), <strong>Links</strong>, <strong>Tid og SLA</strong> og <strong>Historik</strong> er faner ved siden af. Værktøjslinjen og alle kontroller er de samme som i læseruden - kun placeringen ændres. En sags egen <strong>tjekliste</strong> viser hvert trin med sit afkrydsningsfelt på fanen Arbejde; <strong>Fold sammen</strong> viser kun det næste trin (huskes i din browser), og <strong>Åbn i vindue</strong> åbner den stadig for sig selv.',
            'ws_admin' => '<strong>En administrator slår det til</strong> i <strong>Sager &rarr; Indstillinger &rarr; Generelt &rarr; Sagsarbejdsområde</strong>: <em>Fra</em> (standard), <em>Kun sager gjort til et arbejdsområde</em> eller <em>Alle sager</em>.',
            'ws_make' => '<strong>Gør en sag til et arbejdsområde:</strong> i den midterste indstilling åbner du sagen og vælger <strong>Mere &rarr; Gør til arbejdsområde</strong> (og <strong>Tilbage til læseruden</strong> for at fortryde). Det hører til sagen, så alle, der arbejder med den, ser den på samme måde, og det registreres i sagens historik.',
            'ws_own' => '<strong>Dit eget valg:</strong> når det er slået til, slår <strong>Brug arbejdsområdet</strong> i listens filtermenu eller i <strong>System &rarr; Indstillinger</strong> det fra for dig alene. En sag gjort til et arbejdsområde viser derefter et lille mærke <em>Arbejdsområde</em>, så du ved, at en kollega arbejder med den på den måde.',
            'ws_checklist' => '<strong>Sagens tjeklister viser hvert trin:</strong> på fanen <strong>Arbejde</strong> viser en tjekliste alle sine trin med deres afkrydsningsfelter. <strong>Fold sammen</strong> skrumper den til kun det næste trin, som læseruden viser den, og <strong>Fold ud</strong> bringer resten tilbage - din browser husker, hvad du valgte. <strong>Åbn i vindue</strong> åbner stadig den fulde tjekliste i et vindue.',
            'ws_tasks' => '<strong>Tilknyttede opgaver åbner på stedet:</strong> klik på en opgave på fanen <strong>Arbejde</strong>, og dens egen editor åbner dér - tjeklister, formularer, procedurer, delopgaver, kommentarer og dokumenter inkluderet. <strong>Åbn separat</strong> åbner den i sit eget vindue som før; Ctrl-klik gør det samme. Du skal have adgang til Opgaver for at redigere den.',
            'ws_safe' => '<strong>Intet halvskrevet går tabt:</strong> hvis du går til en anden sag eller slår arbejdsområdet fra med et svar, en note eller en opgaveændring uden at have gemt, bliver du spurgt først, og der ventes på alt, der stadig gemmes.',
            'tb_title' => 'Sagstabellen',
            'tb_what' => 'Vælg <strong>Tabel</strong> i stedet for <strong>Beskeder</strong> i handlingsrækken øverst i Sager (eller i <strong>System &rarr; Indstillinger</strong>). Den mappe, du er i, bliver tabellens filter; vælg kolonner, filtrér og sortér dem, søg, og bevæg dig gennem listen 25, 50 eller 100 sager ad gangen. <strong>Gem visning</strong> gemmer et layout til dig selv, dit team eller alle.',
            'tb_same' => 'Klik, Ctrl- og Shift-klik, højreklik, træk til en mappe og masserhandlingerne virker alle, som de gør i beskedlisten, og tabellen viser aldrig en sag, som listen ikke ville vise.',
            'tb_export' => '<strong>CSV-eksport:</strong> CSV-knappen eksporterer <em>hver</em> sag, der matcher, ikke bare siden, med de kolonner, du viser. Hvem der må bruge den, indstilles i <strong>Sager &rarr; Indstillinger &rarr; Generelt &rarr; Hvem må eksportere sagslisten</strong>: kun administratorer (standard), alle med adgang til Sager eller ingen. Knappen vises ikke for nogen, den ikke er åben for.',
            'tb_columns' => '<strong>Hvem en sag er til:</strong> kolonnerne <strong>Anmelder</strong> og <strong>Anmelders e-mail</strong> viser den person, sagen blev oprettet for, og deres e-mailadresse. De er skjult, indtil du markerer dem i <strong>Kolonner</strong>; begge kan sorteres, og begge kommer med i CSV-eksporten, når de vises.',
        ],
        'page_title' => 'Service Desk - guide til sager',
        'sidebar_title' => 'Guide',
        'hero_title' => 'Guide til modulet Sager',
        'hero_sub' => 'Registrér, følg og løs it-supporthenvendelser fra én mappebaseret indbakke &mdash; bygget til service desk-teams.',
        'nav' => [
            'overview' => 'Overblik',
            'inbox' => 'Indbakken',
            'working_with_tickets' => 'Arbejd med sager',
            'working_faster' => 'Arbejd hurtigere',
            'comments_attachments' => 'Kommentarer &amp; vedhæftede filer',
            'ai_tools' => 'AI-værktøjer',
            'csat' => 'CSAT-undersøgelser',
            'user_management' => 'Brugerstyring',
            'dashboard' => 'Dashboard',
            'calendar_rota' => 'Kalender &amp; vagtplan',
            'settings' => 'Indstillinger',
            'tips' => 'Gode råd',
            'companies' => 'Virksomheder',
        ],
        'overview' => [
            'heading' => 'Overblik',
            'intro' => 'Modulet Sager er kernen i din it-service desk. Det giver en velkendt e-mail-lignende grænseflade til at håndtere supporthenvendelser, hændelser og serviceopgaver. Sager kommer ind fra slutbrugere via e-mail eller manuel oprettelse, og medarbejderne arbejder sig gennem dem ved hjælp af mapper, prioriteter og SLA-timere &mdash; alt hvad du behøver for at levere lydhør it-support.',
            'card_inbox_title' => 'Indbakke',
            'card_inbox_body' => 'En mappebaseret indbakke modelleret efter et e-mailprogram. Gennemse mapperne Mine sager, Ikke tildelt, Alle åbne og Lukkede. Klik på en sag for at åbne et læsevindue med alle detaljer, historik og handlinger.',
            'card_dashboard_title' => 'Dashboard',
            'card_dashboard_body' => 'Byg et personligt dashboard med tilpasselige Chart.js-widgets. Visualisér sagsmængder, svartider, kategorifordelinger og medarbejdernes arbejdsbyrde med søjle-, cirkel-, ring- og linjediagrammer.',
            'card_calendar_title' => 'Kalender',
            'card_calendar_body' => 'Se sager i et kalendergitter baseret på deres oprettelses-, frist- eller løsningsdato. Find hurtigt forsinkede sager, og planlæg din uge ved at få et samlet overblik over sagsbilledet.',
            'card_rota_title' => 'Vagtplan',
            'card_rota_body' => 'Planlæg medarbejdervagter og tilkaldevagter. Se hvem der er tilgængelig når som helst, planlæg dækning i weekender og på helligdage, og sørg for at ingen sag bliver overset.',
        ],
        'inbox' => [
            'heading' => 'Indbakken',
            'intro' => 'Indbakken er medarbejdernes primære arbejdsområde. Den bruger et tre-panelet layout &mdash; mapper til venstre, en sagsliste i midten og et læsevindue til højre &mdash; så du kan triagere og svare uden nogensinde at forlade siden.',
            'p_live' => '<strong>Den holder sig selv opdateret.</strong> Hvert minut tjekker indbakken dine postkasser og leder efter noget nyt på sager, du kan se &mdash; en e-mail hentet i baggrunden, en besked fra WhatsApp, Telegram, Slack, Teams eller Mattermost, et svar fra en kollega &mdash; og når noget er ankommet, opdateres listen og mappetallene af sig selv, ligesom med opdateringsknappen. Den sag, du læser, og et svar, du skriver, bliver ikke berørt.',
            'p_folders' => 'Mappepanelet organiserer sager i logiske grupper. Hver mappe viser et ulæst-antal, så du straks kan få øje på nyt arbejde:',
            'field_my' => '<strong>Mine sager</strong> &mdash; sager tildelt dig. Det er din personlige kø og det bedste sted at starte hver dag.',
            'field_unassigned' => '<strong>Ikke tildelt</strong> &mdash; sager der er kommet ind, men endnu ikke har en medarbejder. Tag sager herfra for at overtage ejerskabet.',
            'field_all_open' => '<strong>Alle åbne</strong> &mdash; alle sager der endnu ikke er lukket, uanset hvem der ejer dem. Nyttig for ledere og teamledere, der følger den samlede mængde.',
            'field_closed' => '<strong>Lukkede</strong> &mdash; løste sager. Søg her, når du skal slå en tidligere løsning op eller genåbne en sag.',
            'field_dept' => '<strong>Afdelingsmapper</strong> &mdash; sager grupperet efter afdeling (f.eks. IT, HR, Økonomi). Afdelinger konfigureres under Indstillinger og vises automatisk som undermapper.',
            'switch_heading' => '<strong>Skift mellem gruppering efter afdeling og medarbejder</strong>',
            'switch_body' => 'En lille to-knappers vippe øverst i mappepanelet skifter mellem to visninger af de samme data. Gruppering efter <strong>Afdeling</strong> (standard) viser sager under hver afdeling med status-undermapper indeni; gruppering efter <strong>Medarbejder</strong> vender det om, så hver topmappe repræsenterer én medarbejders personlige kø med status-undermapper indeni. Mappen <strong>Ikke tildelt</strong> er kontekstafhængig i begge visninger &mdash; i afdelingsvisning viser den sager uden afdeling; i medarbejdervisning viser den sager uden tildelt medarbejder &mdash; så du altid kan se, hvad der mangler at blive taget. Dit valg gemmes pr. medarbejder, så hvert teammedlem beholder den visning, de foretrækker, på tværs af sessioner.',
            'p_actions' => 'Over sagslisten har du fire handlingsknapper: <strong>Ny</strong> til at oprette en sag, <strong>Søg</strong> til at finde sager på nøgleord, reference eller anmelder, <strong>Filter</strong> til at indsnævre, hvad du ser, og <strong>Opdatér</strong> til at genindlæse den aktuelle mappe.',
            'filter_body' => 'Knappen <strong>Filter</strong> (tragten) indsnævrer mapperne og listen sammen, uanset hvordan de er grupperet. <strong>Mine</strong> viser kun sager, der er tildelt dig, og <strong>Skjul lukkede</strong> udelader alle sager, hvis status er markeret som lukket. Mens et filter er slået til, har tragten en prik, og en etiket vises ved siden af listens titel, så du altid ved, at du ikke ser det hele. Når mapperne er grupperet efter <strong>Medarbejder</strong>, ligger din egen mappe øverst som <strong>Mine sager</strong> i stedet. Søgning har sin egen kontakt, <strong>Medtag lukkede sager</strong>, som er slået til som standard, fordi en søgning som regel er jagten på en gammel sag. Begge valg gemmes kun for dig.',
            'row_name' => 'Hver række viser sagsreferencen og derefter et navn. Som standard er det <strong>den person, der oprettede sagen</strong>, og det forbliver det samme i hele sagens levetid. Hvis du hellere vil se den, der sendte den seneste besked &mdash; hvilket bliver din egen postkasse, når du har svaret &mdash; skal du ændre <strong>Navn ved siden af sagsnummeret</strong> under <strong>Indstillinger &rarr; Rækkevisning</strong>, hvor du også kan skjule navnet og kun lade referencen stå. Den fane er din egen indstilling: den ændrer intet for andre.',
            'tip' => 'Klik på en sag i listen for at indlæse den i læsevinduet. Herfra kan du opdatere felter, tilføje kommentarer, svare via e-mail eller vedhæfte filer &mdash; alt sammen uden at forlade indbakken.',
        ],
        'live' => [
            'heading' => 'Liveopdateringer',
            'body' => 'FreeITSM holder din skærm i takt med alle andre. Når en kollega ændrer en sag - dens status, prioritet, ejer eller team, et svar, en note - følger din sagsliste og den sag, du har åben, med inden for omkring 15 sekunder, uden at du trykker på opdatér. Opgavetavlen, en åben opgave og klokken virker på samme måde.',
            'what' => 'Den tjekker kun, mens fanen er foran dig, og indhenter ændringer i det øjeblik, du vender tilbage til den. En ændring, du laver i én fane, vises straks i dine andre faner.',
            'safe' => 'Den smider aldrig det væk, du er i gang med. Mens du skriver et svar eller en note, skriver i et felt eller har en menu åben, vises nye beskeder stadig i samtalen, og resten venter bag en lille prompt: <strong>Opdateret af en anden lige nu &middot; Opdatér</strong>.',
            'setting' => '<strong>Indstillinger &rarr; Liveopdateringer</strong> vælger hvert 15. sekund (standard), 30 sekunder, hvert minut eller fra.',
        ],
        'watch' => [
            'heading' => 'Følg en sag',
            'body' => 'Følg en sag uden at eje den - en teamleder, der holder øje med en større hændelse, eller medarbejderen, der gav den videre. Følgere får besked om sagen, som om den var deres, gennem deres egne notifikationsindstillinger.',
            'how' => '<strong>Følg</strong> i sagens værktøjslinje, eller højreklik på den i listen og vælg <strong>Følg</strong>. Højreklik på en markering for at følge dem alle. På en sag, du allerede følger, siger værktøjslinjens knap og højreklikmenuen i stedet <strong>Hold op med at følge</strong> - en markering kan følges, men ikke stoppes på én gang.',
            'others' => 'Knappen <strong>Følg</strong> viser, hvem der følger. Med skriveadgang til Sager kan du <strong>tilføje en kollega</strong> eller tage nogen af; alle kan tage sig selv af.',
            'what' => '<strong>Sager &rarr; Indstillinger &rarr; Generelt &rarr; Følg sager</strong> vælger, hvad følgere hører om - svar, noter, status, prioritet, ny tildeling, SLA-advarsler og overskridelser - alle, medmindre en administrator fjerner markeringen ved nogle. En ny tildeling når en følger som "tildelt en anden", aldrig "tildelt dig", og den har sin egen kontakt i hver persons indstillinger.',
            'leaver' => 'En deaktiveret medarbejder får aldrig besked om en sag, de følger. <strong>Sager &rarr; Indstillinger &rarr; Generelt &rarr; Når en følger deaktiveres</strong> afgør, hvad der sker med deres følgninger: <strong>Hold op</strong> (standard) skjuler dem og sætter dem tilbage, hvis medarbejderen aktiveres igen; <strong>Fjern</strong> tager medarbejderen af alle sager, de følger, når de deaktiveres.',
            'note' => 'Kun personer, der kan se en sag, kan følge den, og hvis de holder op med at kunne se den, holder de op med at høre om den. Ingen får besked om deres egen ændring. Sammenlægning flytter følgere til den sag, der består.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Formularer på en sag',
            'body' => 'Vedhæft en formular fra modulet Formularer til en sag og udfyld den dér - en anmodning om en ny medarbejder, der skal have sin udstyrsformular, eller en sikkerhedshændelse, der skal have sin rapport. Svarene gemmes sammen med sagen.',
            'switch' => '<strong>Sager &rarr; Indstillinger &rarr; Tjeklister &rarr; Formularer på sager</strong> slår det til (det er slået fra, indtil du gør det, og modulet Formularer skal også være slået til). En knap <strong>Formularer</strong> vises så i hver sags værktøjslinje, med et antal af, hvor mange der er indsendt. I et arbejdsområde vises formularerne også på fanen <strong>Arbejde</strong>. Højreklik på en sag eller en markering og vælg <strong>Tilføj formular</strong> for at tilføje en uden at åbne den.',
            'how' => '<strong>Formularer</strong> åbner listen: <strong>Tilføj</strong> vælger en formular (altid dens nyeste version), <strong>Udfyld</strong> åbner den i et vindue, <strong>Gem kladde</strong> beholder halvfærdige svar, som kolleger kan fortsætte med, og <strong>Ret</strong> erstatter en besvarelse, mens den gamle bevares i Formularer.',
            'required' => 'Hver formular er <strong>Påkrævet - blokerer lukning</strong>, <strong>Påkrævet - advarer ved lukning</strong> eller <strong>Valgfri</strong>. En blokerende formular skal indsendes, før sagen kan nå en lukket status; en advarende spørger og registrerer, hvem der lukkede den alligevel.',
            'note' => 'At udfylde en formular kræver skriveadgang til Formularer og til Sager. At læse svarene kræver adgang til Formularer eller rettigheden <strong>Læs formularsvar på sager, du kan se</strong> (en rolleindstilling); alle andre ser, hvem der indsendte den og hvornår, men ikke hvad de skrev. En besvarelse, en sag er afhængig af, kan ikke slettes fra Formularer. Svar vises i sagens sagsrapport og i REST API\'et.',
        ],
        'faster' => [
            'heading' => 'Arbejd hurtigere',
            'intro' => 'Fire ting, der forvandler en travl morgen til en overkommelig én: gemte svar, at handle på mange sager på én gang og at placere samtaler dér, hvor de hører hjemme.',
            'templates_heading' => 'Standardsvar',
            'templates_body' => 'Du sender de samme få svar hele tiden. Skriv et én gang, og klik derefter på <strong>Skabeloner</strong> nederst til venstre i svarvinduet for at sætte det ind ved markøren &mdash; det tilføjes til det, du allerede har skrevet, i stedet for at erstatte det. Skabeloner er formateret tekst og understøtter de samme <code>[merge_code]</code>-pladsholdere som de automatiske e-mails, så <code>[requester_first_name]</code> bliver til det rigtige navn, når du indsætter den.',
            'templates_team' => '<strong>Team-skabeloner</strong> &mdash; delt med alle, oprettet under Indstillinger &rarr; Svarskabeloner.',
            'templates_mine' => '<strong>Dine egne</strong> &mdash; gem et udkast med <em>Gem udkast som skabelon</em>. Kun synlig for dig, og der kræves ingen rettighed.',
            'templates_tip' => 'Navngiv en skabelon efter situationen ("Printer offline &mdash; første skridt"), ikke efter ordlyden. Det er det, du vil lede efter klokken 9.',
            'select_heading' => 'Vælg flere sager',
            'select_body' => 'Sagslisten fungerer som Outlook eller Stifinder. Ingen afkrydsningsfelter.',
            'key_click' => 'Klik',
            'key_click_d' => 'vælg én og åbn den',
            'key_ctrl' => 'Ctrl+klik',
            'key_ctrl_d' => 'tilføj eller fjern én, uden at røre resten',
            'key_shift' => 'Shift+klik',
            'key_shift_d' => 'vælg en hel blok fra der, hvor du sidst klikkede',
            'key_kb' => 'Tastatur',
            'key_kb_d' => 'piletaster for at flytte, Shift+piletaster for at udvide, Ctrl+piletaster og mellemrum for at vælge spredte sager, Ctrl+A for alt, Escape for at rydde',
            'select_actions' => 'Med flere valgt kan du <strong>højreklikke på en af dem</strong> for at sætte status, prioritet, afdeling, type eller tildelt medarbejder for dem alle på én gang &mdash; eller trække hele sættet ind på en mappe. Hvad skærmen viser, mens flere er valgt, er dit eget valg, i kontomenuen under Indstillinger.',
            'select_tip' => 'Højreklikker du på en sag, der <em>ikke</em> er en del af din markering, ryddes markeringen, og handlingen retter sig kun mod den ene. Det er med vilje &mdash; du kan aldrig komme til at handle på et sæt, du troede du var færdig med.',
            'merge_heading' => 'Flet dubletter',
            'merge_body' => 'Har to personer indberettet den samme nedbrud? Vælg sagerne, højreklik, <strong>Flet</strong>. Samtalerne samles, og hvis du har en AI-udbyder konfigureret, skriver FreeITSM en kort briefing om, hvad alle har spurgt om, og hvad der allerede er gjort, så den, der overtager sagen, ikke skal læse fire tråde.',
            'merge_tip' => 'Intet slettes nogensinde. Den sammenlagte sag beholder sit referencenummer, forbliver søgbar, viser hvor den blev flyttet hen &mdash; og en kunde, der svarer på en gammel e-mail om den, når stadig frem til dig.',
            'split_heading' => 'Opdel en sag',
            'split_body' => 'Den modsatte opgave. Når nogen rejser en ny, urelateret ting midt i en samtale, skal du klikke på <strong>Opdel</strong> på den besked (eller højreklikke på beskedens overskrift). Den flyttes til en ny sag, valgfrit med alle nyere beskeder med sig, og den oprindelige sag beholder en markering, der viser, hvor de blev flyttet hen.',
            'split_tip' => 'Giv den nye sag et ordentligt emne. Den bruger som standard den flyttede beskeds emne, som som regel er et "SV:" på det <em>gamle</em> problem.',
            'undo_heading' => 'Fortrudt?',
            'undo_body' => 'Begge dele kan fortrydes fra bjælken på sagen. At fortryde en <strong>opdeling</strong> afvises, så snart nogen har svaret på den nye sag, tilføjet en note eller registreret tid &mdash; du får at vide præcis, hvad der er i vejen. At fortryde en <strong>fletning</strong> giver sagen dens beskeder, noter og registreret tid tilbage og genåbner den præcis som den var, men svar skrevet på den anden sag siden fletningen bliver der.',
        ],
        'working' => [
            'heading' => 'Arbejd med sager',
            'intro' => 'Enhver supporthenvendelse følger et livsforløb: den oprettes, triageres, arbejdes på og til sidst løses. Modulet Sager giver dig værktøjerne til at håndtere hvert trin effektivt, fra første registrering til afslutning.',
            'creating_heading' => '<strong>Opret en ny sag</strong>',
            'step1' => '<strong>Klik på Ny</strong> &mdash; åbn dialogboksen for ny sag fra indbakkens værktøjslinje. Indtast anmelderens navn og e-mailadresse, så vedkommende kan modtage opdateringer.',
            'step2' => '<strong>Angiv emnet</strong> &mdash; skriv et klart, kortfattet resumé af problemet. Det vises i sagslisten og i alle e-mailnotifikationer, der sendes til slutbrugeren.',
            'step3' => '<strong>Vælg afdeling, type og prioritet</strong> &mdash; vælg den rette afdeling, sagstype (f.eks. hændelse, serviceanmodning) og prioritetsniveau. Disse felter styrer SLA-timere og fordelingsregler.',
            'step4' => '<strong>Tilføj beskrivelsen</strong> &mdash; angiv alle detaljer om problemet i tekstredigeringsværktøjet. Medtag trin til at genskabe problemet, fejlmeddelelser og anden relevant kontekst, som den medarbejder, der løser sagen, får brug for.',
            'step5' => '<strong>Gem</strong> &mdash; sagen oprettes med et unikt referencenummer og vises i den rette mappe. SLA-uret starter med det samme ud fra prioriteten.',
            'editing_heading' => '<strong>Redigér og administrér sager</strong>',
            'editing_body' => 'Når en sag først er oprettet, kan du opdatere ethvert felt fra læsevinduet. Vigtige felter omfatter:',
            'card_status_title' => 'Status',
            'card_status_body' => 'Følg sagens livsforløb: Ny, Åben, I gang, Afventer, Løst, Lukket',
            'card_priority_title' => 'Prioritet',
            'card_priority_body' => 'Angiv hastegrad og påvirkning: Kritisk, Høj, Middel, Lav. Hvert niveau har sit eget SLA-mål',
            'card_category_title' => 'Kategori',
            'card_category_body' => 'Klassificér problemtypen: Hardware, Software, Netværk, Adgang, Generel. Nyttig til rapportering',
            'card_analyst_title' => 'Tildelt medarbejder',
            'card_analyst_body' => 'Den person, der er ansvarlig for at løse sagen. Ændring af tildeling logges i aktivitetssporet',
            'card_enduser_title' => 'Slutbruger',
            'card_enduser_body' => 'Den person, der har rejst henvendelsen. Slå op på navn eller e-mail for at knytte til en eksisterende brugerpost',
            'card_dept_title' => 'Afdeling',
            'card_dept_body' => 'Fordel sager til det rette team. Afdelinger styrer mappegruppering og dashboard-filtre',
            'flow_new' => 'Ny',
            'flow_in_progress' => 'I gang',
            'flow_resolved' => 'Løst',
            'flow_closed' => 'Lukket',
            'triage_heading' => '<strong>Triagering med træk og slip</strong>',
            'triage_body' => 'Du behøver ikke åbne en sag for at triagere den. Træk en hvilken som helst række fra sagslisten ind på en mappe for at opdatere felter i én bevægelse:',
            'triage_dept' => '<strong>Afdelingsvisning</strong> &mdash; slip på en afdelingsmappe for at flytte tildelingen, slip på en status-undermappe under en afdeling for at opdatere begge dele på én gang, slip på <strong>Ikke tildelt</strong> for at rydde afdelingen.',
            'triage_analyst' => '<strong>Medarbejdervisning</strong> &mdash; slip på en medarbejders mappe for at gøre den pågældende medarbejder til ejer (sætter både <code>assigned_analyst_id</code> og <code>owner_id</code>, så feltet Ejer i læsevinduet holdes synkroniseret), slip på en status-undermappe for at opdatere begge dele, slip på <strong>Ikke tildelt</strong> for at rydde tildelingen.',
            'triage_spring' => '<strong>Fjedrende mapper</strong> &mdash; hold musen over en sammenklappet mappe under et træk, så udfolder den sig automatisk (som i Outlook), så enhver indlejret status kan nås uden først at slippe.',
            'fullscreen_heading' => '<strong>Fuldskærmsvisning</strong>',
            'fullscreen_body' => 'Når du skal fokusere på én sag &mdash; en lang samtale, en kompleks ændring, et detaljeret svar under udarbejdelse &mdash; kan du skifte til fuldskærmsvisning. Mappelisten og sagslisten forsvinder, samtalen udfylder den tilgængelige bredde, og egenskaberne (Afdeling, Type, Status, Oprindelse, Løst ved første kontakt, IT-oplæring, Ejer) flyttes til en lodret sidebjælke til højre.',
            'fullscreen_max' => '<strong>Maksimér-ikonet</strong> &mdash; lille ikon i højre ende af sagens emnelinje. Klik for at gå i fuldskærm; klik igen for at vende tilbage til 3-panel-layoutet.',
            'fullscreen_dbl' => '<strong>Dobbeltklik på en række</strong> &mdash; dobbeltklik på en sag i listen for at åbne den direkte i fuldskærm, en "åbn denne nu"-handling som i Outlook.',
            'fullscreen_sticks' => '<strong>Følger med på tværs af valg</strong> &mdash; når du først er i fuldskærm, forbliver du der, når du skifter til den næste sag. En frisk genindlæsning af siden (F5) uden en valgt sag vender tilbage til standard 3-kolonne-layoutet, så du aldrig kan ende fanget med mappelisten skjult.',
            'fullscreen_back' => '<strong>Tilbage</strong> &mdash; bjælken over sagen viser dens reference og en knap <strong>Tilbage</strong>, som fører dig direkte tilbage til listen, præcis som du forlod den, med tastaturet tilbage på listen - så piletasterne bevæger sig mellem sager, og Enter åbner den næste med det samme. <strong>Escape</strong> gør det samme, så snart et vindue eller en menu, der er åben over sagen, er lukket. Ingen af dem slår fuld skærm fra: den næste sag åbner stadig i fuld skærm (formindskelsesikonet er kontakten), og når du går tilbage til den sag, du forlod, finder du et påbegyndt svar stadig der.',
            'fullscreen_keys' => '<strong>Tasterne ruller sagen</strong> &mdash; i fuld skærm ruller piletasterne, Page Up / Page Down og mellemrum samtalen, ikke den skjulte sagsliste. I et billed- eller PDF-vindue ruller de dette vindue. I den almindelige visning med tre ruder skal du klikke i sagen, så ruller tasterne den også; klik på listen for at gå tilbage til at bevæge dig mellem sager.',
            'viewer_heading' => '<strong>Billeder og PDF\'er åbner over sagen</strong>',
            'viewer_body' => 'Klik på et billede eller en PDF, der er vedhæftet en note, eller et i sagens liste <strong>Vedhæftede filer</strong> (dens miniature eller dens række), og det åbner i et vindue oven på sagen &mdash; samme fremviser som i modulet Filer. Sagen bliver præcis, hvor den var, nedenunder.',
            'viewer_window' => '<strong>Flyt det og ændr størrelsen</strong> &mdash; træk i titellinjen for at flytte vinduet og i en kant eller et hjørne for at ændre størrelsen; dobbeltklik på titellinjen, eller træk den til skærmens top, for at fylde skærmen. Billedet eller PDF\'en tilpasses igen, når vinduets størrelse ændres, indtil du selv zoomer ind eller ud &mdash; <strong>Tilpas</strong> giver den tilbage. Åbn flere, og de ligger side om side.',
            'viewer_close' => '<strong>Luk det</strong> &mdash; &times; i dets titellinje eller <strong>Escape</strong> (som lukker vinduet forrest). <strong>Download</strong> gemmer filen. På en telefon åbner filen i fuld skærm med en knap Tilbage.',
            'viewer_other' => '<strong>Andre filer</strong> &mdash; Word-dokumenter, regneark og alt andet downloades eller åbnes stadig i en ny fane, som før. For i stedet at åbne en notes billede eller PDF i en ny fane skal du Ctrl-klikke på det.',
            'paste_heading' => '<strong>Indsæt et skærmbillede i en note</strong>',
            'paste_body' => 'Kopiér et skærmbillede, klik ind i feltet <strong>Tilføj note</strong> og tryk <strong>Ctrl+V</strong>. Billedet kommer ind, hvor markøren er, med din tekst før og efter, og bliver på det sted, når noten er gemt. Klik på det for at åbne det i fremviseren. <strong>Backspace</strong> fjerner det, før du gemmer.',
            'paste_shared' => '<strong>Delte noter deler deres billeder</strong> &mdash; anmelderen ser dem i portalen, på stedet. På en intern note er de lige så private som noten.',
            'paste_save' => '<strong>Intet gemmes, før du trykker Gem</strong> &mdash; luk feltet, og billederne forsvinder med det. Hvis et billede afvises, gemmes noten heller ikke, årsagen vises, og din tekst er stadig i feltet.',
            'paste_text' => '<strong>Tekst forbliver tekst</strong> &mdash; indsættes der fra Word, en webside eller Excel, kommer ordene ind uden deres formatering. Knappen <strong>Vedhæft</strong> virker stadig til alle andre filer.',
            'rightclick_heading' => '<strong>Højreklik for hurtige handlinger</strong>',
            'rightclick_body' => 'Højreklik på en sag i listen for at åbne en genvejsmenu. Menuen viser sagens referencenummer øverst, så du ved, hvad du handler på, og enhver handling påvirker den sag, du højreklikkede på, <em>uden</em> at ændre det, der aktuelt er åbent i læsevinduet &mdash; nyttigt når du læser sag A og skal triagere sag B uden at miste dit sted.',
            'rightclick_status' => '<strong>Sæt status &rarr;</strong> &mdash; undermenu, der viser alle aktive statusser med deres farveprøve. Der vises et flueben ud for den aktuelle værdi, hvis du højreklikker på den sag, du har åben. Et valg opdaterer straks sagen, skriver en post i aktivitetssporet, opdaterer mappeantallene og synkroniserer status-rullelisten i læsevinduet, hvis relevant.',
            'rightclick_priority' => '<strong>Sæt prioritet &rarr;</strong> &mdash; samme undermenu-mønster, hentet fra de aktive prioriteter med hver sin farve som prøve. Den øverste række er en valgmulighed <em>(ingen prioritet)</em> til at rydde tildelingen (prioritet kan være tom).',
            'rightclick_assign' => '<strong>Tildel til &rarr;</strong> &mdash; undermenu, der viser alle indlæste medarbejdere med et gråt initialmærke, plus en række <em>(ikke tildelt)</em> øverst til at rydde. Et valg sætter både <code>assigned_analyst_id</code> OG <code>owner_id</code>, så feltet Ejer i læsevinduet holdes synkroniseret.',
            'rightclick_cmdb' => '<strong>Kæd CMDB-objekt&hellip;</strong> &mdash; åbner en søg-mens-du-skriver-vælger. Klik på et resultat for at knytte det, og fortsæt med at vælge &mdash; feltet ryddes og får fokus igen til det næste, og en "Senest tilknyttet"-log inde i dialogboksen viser din løbende liste over grønne flueben.',
            'rightclick_time' => '<strong>Registrér tid&hellip;</strong> &mdash; åbner en dialogboks med minutter + en dato/tid-vælger (som standard sat til "nu", så du også kan bagdatere) + et valgfrit notefelt.',
            'rightclick_more' => '<strong>Vedhæft tjekliste &rarr;</strong>, <strong>Tilføj formular &rarr;</strong> og <strong>Følg</strong> - vedhæft en tjekliste (bedste match først), tilføj en formular, eller følg sagen uden at åbne den. På en markering virker de på hver markeret sag og springer dem over, der allerede har den tjekliste eller formular.',
            'rightclick_phone' => '<strong>På en telefon</strong> skal du trykke og holde på en sag i et halvt sekund for at åbne den samme menu som et panel i fuld skærm. Et valg med flere muligheder &mdash; Sæt status, Sæt prioritet, Tildel til &mdash; glider hen til dem, med <strong>Tilbage</strong> for at vende tilbage.',
            'rightclick_tip' => 'Hvis den sag, du handler på via genvejsmenuen, tilfældigvis er den samme, der er åben i læsevinduet, opdateres det relevante afsnit dér (rullelisterne Status/Prioritet, CMDB-objekter, tidsregistreringer) automatisk, når dialogboksen lukkes, så brugerfladen forbliver synkroniseret.',
            'time_heading' => '<strong>Registrering af tid</strong>',
            'time_body' => 'Tid brugt på en sag logges i et dedikeret afsnit <strong>Tidsregistreringer</strong> i læsevinduet, placeret mellem panelet med tilknyttede CMDB-objekter og notepanelet. Overskriften viser den løbende sum (f.eks. "I alt 2t 30m"), og hver registrering nedenunder viser den brugte tid, medarbejderen, datoen og eventuelle noter, du har tilføjet.',
            'time_step1' => '<strong>Indbygget formular</strong> &mdash; indtast de brugte minutter i taltfeltet, en valgfri kort beskrivelse i notefeltet, og klik på <strong>Tilføj</strong>. Den nye registrering vises straks øverst i listen med dit navn og det aktuelle tidsstempel.',
            'time_step2' => '<strong>Bagdatér via højreklik</strong> &mdash; hvis du skal registrere tid, du glemte tidligere, kan du højreklikke på sagen i listen og vælge <strong>Registrér tid&hellip;</strong>. Dialogboksen indeholder en dato/tid-vælger, så du kan stemple registreringen med det faktiske tidspunkt, arbejdet blev udført.',
            'time_step3' => '<strong>Slet dine egne registreringer</strong> &mdash; en lille &times;-knap vises ved siden af registreringer, du selv har lavet. Klik på den (og bekræft) for at soft-slette &mdash; rækken bliver i databasen med <code>is_active = 0</code> af hensyn til revision, men forsvinder fra listen. Du kan ikke slette andre medarbejderes registreringer.',
            'time_tip1' => 'Tid gemmes som almindelige minutter (45 min, 90 min osv.) og vises som <code>45m</code> eller <code>1t 30m</code> i brugerfladen &mdash; præcist nok til korte rettelser, uden besvær med decimaltimer.',
            'time_tip2' => 'Enhver feltændring registreres i sagens aktivitetsspor. Du kan altid se, hvem der ændrede hvad og hvornår, hvilket er afgørende for revisionsoverholdelse og overdragelse mellem medarbejdere.',
        ],
        'comments' => [
            'heading' => 'Kommentarer &amp; vedhæftede filer',
            'intro' => 'Aktivitetssporet er hjertet i hver sag. Det registrerer enhver handling &mdash; kommentarer, feltændringer, afsendte e-mails og vedhæftede filer &mdash; i en kronologisk tidslinje, der fortæller hele historien om en supporthenvendelse.',
            'adding_heading' => '<strong>Tilføj kommentarer</strong>',
            'step1' => '<strong>Åbn sagen</strong> &mdash; klik på en sag i indbakken for at indlæse dens læsevindue. Rul ned for at se hele aktivitetssporet og kommentarfeltet nederst.',
            'step2' => '<strong>Skriv din note</strong> &mdash; brug knappen Tilføj note for at åbne kommentareditoren. Noter er interne som standard og kun synlige for medarbejdere på service desken.',
            'step3' => '<strong>Svar eller videresend via e-mail</strong> &mdash; brug handlingerne Svar eller Videresend for at sende en besked til slutbrugeren eller en tredjepart. E-mailen logges i aktivitetssporet sammen med indholdet af den udgående besked.',
            'subject_note' => '<strong>Emnet</strong> &mdash; Svar og Videresend viser emnet, og du kan ændre det. Når du videresender en sag til en ekstern udbyder, og deres svar tilføjer deres eget nummer i emnet (for eksempel <em>#TCK89633 - FW: &hellip;</em>), så brug <strong>Svar</strong> eller <strong>Videresend</strong> på <em>den</em> besked i samtalen: Den starter fra dens emne, så din opfølgning beholder deres nummer og lander på deres sag. Hver besked viser sit eget emne under afsenderen. Sagens reference i kantede parenteser bevares altid &mdash; hvis du fjerner den, sættes den tilbage, når du sender, så svar stadig kommer tilbage til denne sag.',
            'requester_note' => '<strong>Skift af anmelder</strong> &mdash; <strong>Skift anmelder</strong> ved siden af afsenderen øverst på sagen gør sagen til en andens: en kollega, der oprettede den på vegne af en anden, en fejl ved modtagelsen. Det skrives i sagens historik. Når den gamle anmelder ligner den samme person, der skriver fra en anden adresse, får du tilbud om at flette vedkommende ind: deres andre sager flyttes også, og deres adresse bliver en af den nye persons, så deres næste e-mail lander dér. En linje med <strong>Anmelder</strong> under afsenderen vises, når sagen er til en anden end den, der skrev beskeden. Post fra en adresse, der er tilknyttet en person (Personer &rarr; deres side &rarr; E-mailadresser), er deres, så den skaber aldrig en anden person.',
            'addresses_note' => '<strong>Adresser mens du skriver</strong> &mdash; begynd at skrive i <strong>Til</strong> eller <strong>Cc</strong>, og FreeITSM foreslår adresser: først en leverandørs <strong>servicedesk</strong> (angiv den på leverandøren under Kontrakter), derefter leverandørkontakter, personer fra sagens virksomhed og adresser, der for nylig er sendt e-mail til fra den virksomheds sager. Brug piletasterne og Enter, eller klik; vælg så mange, du vil, eller bliv ved med at skrive dine egne. En adresse fra én virksomheds sager foreslås aldrig hos en andens, og hvem en fortrolig sag blev sendt til, foreslås aldrig overhovedet.',
            'attachments_note' => '<strong>Vedhæftede e-mailfiler</strong> &mdash; i listen over vedhæftede filer åbner et klik en fil i et vindue over sagen, hvor filtypen tillader det: billeder, PDF\'er, Word-dokumenter, regneark og CSV-filer, tekst, lyd og video, med en downloadknap. Alt andet downloades. <strong>Gem i Filer</strong> ved siden af hver - og ved siden af hver fil på en note - kopierer den ind i en mappe i Filer. For at lægge en fil, der allerede er i Filer, på sagen bruger du <strong>Fra Filer</strong> i vinduet <strong>Tilføj note</strong> (<strong>Fra computer</strong> er knappen ved siden af) - der åbnes et vindue som en fildialog med mapper til venstre og deres filer til højre - som et link (åbnes via Filer, under mappens rettigheder, vises aldrig i portalen) eller en kopi, som Filer &rarr; Indstillinger &rarr; Deling tillader.',
            'files_heading' => '<strong>Vedhæftede filer</strong>',
            'files_body' => 'Vedhæft skærmbilleder, logfiler, dokumenter eller andre understøttende filer direkte til en sag. Filer kan trækkes ind i dropzonen for vedhæftede filer eller vælges via filvælgeren. Vedhæftede filer gemmes på serveren og knyttes til sagens aktivitetsspor, så intet går tabt.',
            'audit_heading' => '<strong>Revisionslogning</strong>',
            'export_heading' => '<strong>Sagsrapporter</strong>',
            'export_body' => 'Til en gennemgang eller en revisor gør <strong>Eksportér</strong> i sagens værktøjslinje sagen og dens opgaver til én printbar rapport - se <a href="#case-reports">Sagsrapporter</a>.',
            'audit_body' => 'Aktivitetssporet registrerer automatisk enhver handling uden medarbejderens indgriben. Når en prioritet ændres fra Middel til Høj, registreres den gamle og den nye værdi. Når en sag omfordeles, logges både den tidligere og den nye medarbejder. Det skaber en fuldstændig, manipulationssikker historik, der opfylder ITIL-revisionskrav og hjælper ledere med at forstå, hvordan sager håndteres.',
            'tip' => 'Når du svarer via e-mail, kan du tilføje Cc-modtagere og vedhæfte filer i samme handling. Hele e-mailsamtalen tråd-sammenkædes i sagens aktivitetsspor, så al kommunikation samles ét sted.',
        ],
        'ai' => [
            'heading' => 'AI-værktøjer',
            'intro' => 'To Claude-drevne funktioner sidder i selve sagsarbejdsgangen: <strong>Oprydning af svar</strong> omskriver et groft udkast til en ordentligt formateret e-mail, og <strong>Spørg AI</strong> søger i videnbasen på almindeligt sprog ud fra sagens kontekst.',
            'cleanup_heading' => '<strong>Oprydning af svar &mdash; ✨-knappen i svareditoren</strong>',
            'cleanup_body' => 'Skriv et hurtigt, groft udkast i et svar (eller bare punkter som *"skal genstarte udskrivningstjenesten, tag skærmbillede til dem"*), og klik på knappen <strong>✨ Ryd op</strong>. Claude omskriver det til en ordentligt formateret e-mail &mdash; tilføjer en hilsen <em>Kære [name],</em> ud fra anmelderen, retter grammatik, anvender den konfigurerede tone og afslutter med <em>Med venlig hilsen,</em>. Prompten er låst, så den IKKE vil finde på tekniske detaljer, opdigte undskyldninger eller udvide indholdet ud over det, du selv har skrevet.',
            'cleanup_streams' => '<strong>Live-streaming</strong> &mdash; omskrivningen vises i editoren, mens Claude genererer den (ingen ventetid foran en spinner).',
            'cleanup_undo' => '<strong>Fortryd-link i 30 sekunder</strong> &mdash; skulle Claude ødelægge omskrivningen, vises et lille <em>Fortryd</em>-link under editoren i 30 sekunder efter omskrivningen er færdig, som gendanner det oprindelige udkast.',
            'cleanup_tone' => '<strong>Pr. tone</strong> &mdash; tre tone-forudindstillinger, der kan konfigureres under <strong>Indstillinger &rarr; Oprydning af svar</strong>: <em>Venlig</em> (standard), <em>Formel</em>, <em>Kortfattet</em>. Vælg den, der matcher jeres teams stil.',
            'cleanup_key' => '<strong>Egen API-nøgle</strong> &mdash; separat Anthropic-nøgle fra AI-funktionerne til RFP/Viden/Arbejdsgang, så forbruget vises som sin egen linje på Anthropics faktureringsdashboard. Konfigureres under <strong>Indstillinger &rarr; Oprydning af svar</strong>.',
            'cleanup_tip' => 'Oprydning bruges bedst til de rutineprægede svar i stil med "jeg har prøvet dette, prøv venligst X". Til lange, nuancerede beskeder bør du selv skrive dem &mdash; AI\'en er god til struktur, men kender ikke jeres specifikke miljø.',
            'ask_heading' => '<strong>Spørg AI &mdash; 🤖-knappen i sagens værktøjslinje</strong>',
            'ask_body' => 'Klik på knappen <strong>Spørg AI</strong> (🤖) i sagens værktøjslinje for at åbne et chatpanel, der glider ind fra siden, og som kender den åbne sags emne, indhold og kontekst fra læsevinduet. Stil spørgsmål som *"har vi set det her før?"* eller *"hvad plejer at løse denne fejl?"*, og den søger semantisk i <a href="../knowledge/" style="color:#0078d4;">videnbasen</a> (via Claude + OpenAI-embeddings) og svarer med relevante artikler samt direkte links til at åbne dem.',
            'ask_context' => '<strong>Kontekstbevidst</strong> &mdash; panelet ved, hvilken sag du ser på, så du kan stille generelle spørgsmål, og det finder selv den relevante kontekst.',
            'ask_linked' => '<strong>Tilknyttede artikler</strong> &mdash; forslag kan klikkes og åbner den matchende videnartikel i en ny fane.',
            'ask_shared' => '<strong>Delt med modulet Viden</strong> &mdash; AI\'en bruger samme nøgle og model som AI-søgning i Viden, så én konfiguration giver dig begge dele. Se hjælpen til modulet Viden for opsætningsdetaljer.',
        ],
        'csat' => [
            'heading' => 'Tilfredshedsundersøgelser (CSAT)',
            'intro' => 'Send en tilfredshedsundersøgelse fra 1&ndash;5 til anmelderen via e-mail, når en sag er løst, registrér svaret på en landingsside uden login, og følg tendenser pr. medarbejder på en dedikeret analyseside.',
            'modes_heading' => '<strong>To udløsertilstande &mdash; vælg én</strong>',
            'mode_auto' => '<strong>Automatisk ved lukning</strong> &mdash; undersøgelsen sættes automatisk i kø, når en sag skifter til en hvilken som helst lukket status. Medarbejderen behøver ikke gøre noget &mdash; løsningen driver undersøgelsen.',
            'mode_manual' => '<strong>Kun manuelt</strong> &mdash; medarbejderen klikker på knappen ⭐ <strong>Feedback</strong> i sagens værktøjslinje, når vedkommende vil spørge. Nyttigt, hvis du hellere vil afgøre sag for sag, om der skal bedes om feedback.',
            'starters_note' => '<strong>Sager oprettet af et forløb for nyansatte og fratrådte</strong> (et skabelontrin oprettet som en sag) får ingen automatisk undersøgelse, og deres anmelder ingen automatiske e-mails, medmindre skabelonen har flueben ved <strong>Send e-mail til anmelderen om disse sager</strong>. Hver e-mail, der ikke blev sendt, er opført i postkassens afsendelseslog som sprunget over, med årsagen. Sagen viser blandt sine links, hvilket forløb den er til.',
            'switch_note' => 'Bruger du slet ikke CSAT? Slå det fra under <strong>System &rarr; Moduler &rarr; Tilgængelighed &rarr; Sagsfunktioner</strong>, så forsvinder det: ingen undersøgelser, ingen CSAT-side, ingen knap Bed om feedback, og gamle undersøgelseslinks siger, at feedback ikke længere indsamles. Intet slettes.',
            'mode_off' => '<strong>Fra</strong> &mdash; funktionen er slået fra; der sendes ingen undersøgelses-e-mails.',
            'modes_choose' => 'Vælg under <strong>Sager &rarr; Indstillinger &rarr; CSAT</strong>. Den manuelle knap virker stadig i tilstanden <em>automatisk</em> &mdash; medarbejdere kan bede om feedback igen på en sag, der allerede er blevet spurgt, hvis nødvendigt.',
            'template_heading' => '<strong>E-mailskabelonen</strong>',
            'template_body' => 'Indholdet af undersøgelses-e-mailen kommer fra den eksisterende fane <strong>E-mailskabeloner</strong> &mdash; opret en skabelon med hændelsen <strong>CSAT-undersøgelse</strong> (den nye hændelse ved siden af <em>Sag tildelt</em> / <em>Sag lukket</em>), og indsæt merge-koden <code>[csat_link]</code> dér, hvor bedømmelseslinket skal vises. Standard merge-koder (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) er tilgængelige som normalt.',
            'template_tip' => 'Findes der ingen aktiv CSAT-skabelon, afviser knappen <em>Feedback</em> med en tydelig fejl, og den automatiske udløser springes stille over &mdash; du kan aldrig ende med døde undersøgelseslinks.',
            'survey_heading' => '<strong>Undersøgelsessiden</strong>',
            'survey_body' => 'Anmelderen klikker på linket i e-mailen og lander på en side uden login med en vælger fra 1&ndash;5 plus et valgfrit kommentarfelt. To visuelle stilarter, der kan konfigureres under <strong>Indstillinger &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Stjerner</strong> &mdash; klassisk fyld-ved-hover-adfærd, hvor forudgående stjerner fyldes med. Hold musen over stjerne #3, og #1+#2+#3 fyldes i guld. Klik for at låse.',
            'survey_emojis' => '<strong>Emojis</strong> &mdash; 5 ansigter 😡 🙁 😐 🙂 😀 starter i gråtoner med 40 % opacitet; det ansigt, musen er over, eller som er valgt, går tilbage til fuld farve i 1,25&times; størrelse. Klik for at låse.',
            'survey_store' => 'Begge tilstande gemmer det samme tal fra 1&ndash;5, så dashboards og gennemsnit fungerer ens uanset hvilken stil der bruges. Undersøgelses-URL\'en kan kun bruges én gang &mdash; når brugeren har indsendt, afviser det samme link yderligere indsendelser.',
            'chat_heading' => '<strong>Spørg chatkunder i deres chat</strong>',
            'chat_body' => 'Når <strong>Spørg chatkunder i deres chat</strong> er afkrydset, bliver en kunde, der skrev ind på WhatsApp, Telegram, Slack, Microsoft Teams eller Mattermost, spurgt i den chat i stedet for via e-mail &mdash; fem knapper på Telegram, Teams og Mattermost, &ldquo;svar med ét enkelt ciffer&rdquo; andre steder. Svaret havner i de samme resultater som en undersøgelse sendt pr. e-mail.',
            'chat_rules' => 'WhatsApp spørges kun, mens dets 24-timers svarvindue er åbent; uden for det, eller hvis chatbeskeden ikke kan sendes, bruges e-mailundersøgelsen i stedet. Et ciffer tæller kun som en vurdering lige efter spørgsmålet &mdash; i den samme chat, inden for en uge og før kunden har skrevet noget andet &mdash; så &ldquo;3&rdquo; som svar på en medarbejders spørgsmål forbliver en besked. Slået fra efter opgradering; slået til for en ny installation.',
            'analytics_heading' => '<strong>Analysesiden</strong>',
            'analytics_body' => 'Klik på navigationsknappen ⭐ <strong>CSAT</strong> (mellem Vagtplan og Indstillinger) for at åbne analyse-dashboardet på <code>tickets/csat/</code>. Vælg periode: 7 / 30 / 90 / 365 dage.',
            'card_kpi_title' => 'KPI-felter',
            'card_kpi_body' => 'Gennemsnitlig bedømmelse (ud af 5), antal svar, svarprocent (svaret ÷ sendt)',
            'card_dist_title' => 'Fordeling af score',
            'card_dist_body' => 'Søjlediagram over bedømmelser 1-5 med præcise antal og procenter',
            'card_leader_title' => 'Rangliste pr. medarbejder',
            'card_leader_body' => 'Gennemsnitlig bedømmelse + antal svar pr. medarbejder, sorteret efter gennemsnit faldende. Brug den til udviklingssamtaler',
            'card_recent_title' => 'Seneste svar',
            'card_recent_body' => 'Vurderingerne med de nyeste først, 25 pr. side, med deres frie kommentarer og den kunde, der har efterladt dem, linket tilbage til den oprindelige sag',
            'analytics_filters' => 'Indsnævr siden med filtrene under overskriften: et datointerval <strong>Fra / Til</strong> (i stedet for dagknapperne), et <strong>Vurderings</strong>-bånd (Positive 4-5, Neutrale 3, Negative 1-2), en <strong>Medarbejder</strong> og en <strong>Kunde</strong>. Medarbejder og kunde indsnævrer alle tal på siden; vurderingsbåndet indsnævrer kun listen over besvarelser, så gennemsnittet stadig betyder noget. På en telefon ligger filtrene bag knappen <strong>Filtre</strong> nederst på skærmen. En filtreret side kan sættes som bogmærke.',
            'analytics_company' => 'Alle tal følger <strong>virksomhedsvælgeren</strong> i sidehovedet: den virksomhed, du har valgt, eller alle virksomheder, du kan se, under <strong>Alle virksomheder</strong>.',
            'analytics_tip' => 'Tilknytning pr. medarbejder overlever omfordeling af sagen, fordi medarbejderens id fastholdes på undersøgelsesrækken ved afsendelsestidspunktet og ikke slås op på ny senere. Hvis en sag går på omgang, inden den lukkes, er det den medarbejder, der rent faktisk lukkede den, der ejer bedømmelsen.',
            'one_heading' => '<strong>Én undersøgelse pr. sag</strong>',
            'one_body' => 'Er <em>Én undersøgelse pr. sag</em> slået til (standard), får en sag, der genåbnes og derefter lukkes igen, kun endnu en undersøgelse, når en medarbejder aktivt udløser den &mdash; det forhindrer at oversvømme en sag, der cirkulerer frem og tilbage, med undersøgelser. Slå det fra, hvis hver lukning skal udløse en frisk undersøgelse.',
        ],
        'users' => [
            'heading' => 'Brugerstyring',
            'intro' => 'Navigationsknappen <strong>Brugere</strong> åbner <code>tickets/users.php</code> &mdash; et katalog over alle slutbrugere (dem der rejser sager, ikke medarbejdere) sammen med hver enkelts sagshistorik.',
            'p_intro' => 'Brugere kommer ind i systemet på fire reaktive måder &mdash; selvregistrering via portalen, en indgående e-mail fra en ny afsender, postkasse-pollingen eller arbejdsgangsmotoren, der opretter en ud fra en udløst sag. Det dækker de fleste tilfælde, men på siden Brugere kan du også <strong>oprette på forhånd</strong> en bruger (f.eks. en ny medarbejder, der snart får brug for adgang), samt <strong>redigere</strong> eller <strong>slette</strong> eksisterende rækker.',
            'add_heading' => '<strong>Tilføj bruger</strong>',
            'add_body' => 'Knappen <strong>Tilføj</strong> i brugerlistens sidehoved åbner personeditoren. Det er den samme editor, som <strong>Aktiver &rarr; Brugere</strong> åbner, så en person tilføjes og ændres på samme måde, uanset hvilken skærm du er på:',
            'add_email' => '<strong>E-mail</strong> &mdash; valgfri, fordi personer, der logger ind via et katalog, måske ikke har en postkasse; de findes i stedet via deres loginnavn. Angiv enten en e-mailadresse eller et visningsnavn. En adresse skal være unik og må ikke tilhøre en medarbejder.',
            'add_names' => '<strong>Visningsnavn/foretrukket navn</strong> &mdash; valgfrit. Foretrukket navn er det, brugeren selv bliver mødt med i e-mails (f.eks. <em>"Ed"</em> i stedet for <em>"Ed Mozley"</em>).',
            'add_password' => '<strong>Adgangskode</strong> &mdash; valgfrit. Lades feltet tomt, oprettes en konto <em>uden adgangskode</em> &mdash; nøjagtig samme tilstand, som brugere fra indgående sager starter i. Brugeren kan senere overtage kontoen via selvbetjeningsportalens registreringsflow ved selv at sætte en adgangskode.',
            'add_details' => '<strong>Jobtitel, afdeling, kontor, telefon, mobil, medarbejdernummer og leder</strong> &mdash; alle valgfrie, og alle beskriver <em>personen</em> frem for loginnet. Værd at udfylde: <strong>kontor</strong> fortæller dig, hvilket sted nogen befinder sig, før du går og leder efter dem, <strong>leder</strong> registrerer rapporteringslinjen (skriv en del af et navn for at finde dem), og <strong>medarbejdernummer</strong> er sammenkædningsnøglen, når du afstemmer mod et lønsystem, der aldrig har hørt om en e-mailadresse. Når du importerer fra et katalog, ankommer alle disse udfyldt. En CardDAV-adressebog udfylder alt undtagen medarbejdernummer og leder, som et kontaktkort ikke har noget sted at gemme.',
            'managed_heading' => '<strong>Personer vedligeholdt et andet sted</strong>',
            'source_body' => '<strong>Hvor en person kommer fra</strong> er navngivet i deres detaljer (<em>Detaljer fra: Contoso AD - katalog</em>), og filteret <strong>Kilde</strong> under søgefeltet lister kun personerne fra ét katalog eller én adressebog, eller kun dem, der er tilføjet i FreeITSM, med et antal ved siden af hver. Det vises, når nogen først er knyttet til en kilde.',
            'add_book_body' => '<strong>Tilføj til adressebog.</strong> Nogen, der har skrevet ind via e-mail, findes her, men i ingen adressebog. Hvis en administrator har slået <em>Lad medarbejdere tilføje personer til denne adressebog</em> til (System &rarr; Godkendelse, på adressebogen), får den person en knap <strong>Tilføj til adressebog</strong> ved siden af Redigér. Den spørger først, viser hvad der kommer på kortet, og opretter derefter deres kontakt og knytter dem &mdash; den samme person, ikke en kopi. Den vil ikke tilføje nogen, hvis e-mailadresse bogen allerede har (kør importen i stedet), og den sørger for, at den næste import fanger den nye kontakt, eller den tager kortet ud igen.',
            'managed_body' => 'Når en person er importeret &mdash; fra LDAP eller Active Directory, eller fra en CardDAV-adressebog &mdash; er de oplysninger, kilden ejer, <strong>skrivebeskyttede</strong>, og dialogboksen nedtoner dem. Det, de kommer fra, er den autoritative kilde, og den næste import ville overskrive alt, der er skrevet her, så det gemmes slet ikke, i stedet for at blive accepteret og stille og roligt fortrudt en time senere. <strong>Hvilke</strong> oplysninger afhænger af kilden: et katalog ejer alle syv, mens en adressebog ejer fem &mdash; den har intet sted at gemme et medarbejdernummer eller en referencelinje, så de to forbliver dine at udfylde. Og hvis adressebogen har <em>skriv ændringer tilbage</em> slået til, er ingen af dem låst: det, du skriver, sendes til kontaktkortet, så der er intet for den næste import at fortryde. Alt andet på posten, inklusive virksomhed og adgangskode, kan altid redigeres.',
            'edit_heading' => '<strong>Redigér bruger</strong>',
            'edit_body' => 'Vælg en bruger på listen, og klik derefter på <strong>Redigér</strong> i detaljernes sidehoved. Samme editor, forudfyldt. Hvis du gemmer uden en adgangskode, forbliver den eksisterende hash uberørt; hvis du angiver en, nulstilles den. Hvis deres leder er en person i en virksomhed, du ikke kan se, siger Leder-feltet det, og lederen bevares, som vedkommende er, medmindre du vælger en anden.',
            'signin_body' => '<strong>Logger ind med</strong> viser, hvilken single sign-on-udbyder en person er knyttet til. <strong>Fjern tilknytning</strong> ved siden af fjerner efter en bekræftelse denne tilknytning, så deres næste login starter forfra &mdash; for en, der er flyttet til en anden udbyder, eller som blev knyttet til den forkerte konto. Det tilbydes ikke for personer, der administreres af en katalogsynkronisering, som blot ville knytte dem igen.',
            'company_body' => '<strong>Virksomhed</strong> vises, når du har mere end én. For en ny person afgør en tom værdi virksomheden ud fra deres e-mailadresse; for en eksisterende person betyder tom ingen virksomhed, og deres sager går til triage.',
            'managers_heading' => '<strong>Ledere</strong>',
            'managers_body' => 'En person kan gøres til <strong>leder</strong> i selvbetjeningsportalen: de får fanebladet <strong>Teamsager</strong> med en liste over sagerne for de personer, de leder. Det er slået fra, indtil en administrator slår det til under <strong>System &rarr; Ledere</strong>, som også afgør, om ledere må svare på eller lukke disse sager, og hvad de ser af en fortrolig sag (som standard ingenting).',
            'managers_sources' => 'Nogen er leder på to måder, begge på én gang: de er <strong>Leder</strong> på andre personers poster (manuelt eller fra jeres katalog), og de har <strong>ledelseslinjer</strong> sat op for sig. Klik på <strong>Lederadgang</strong> ved siden af Redigér for at åbne en fuldskærmsside for den person, hvor du kan give dem alle, bestemte personer, persongrupper, afdelinger eller hele deres rapporteringslinje, og <strong>udelukke</strong> personer &mdash; en udelukkelse vinder altid, også over Leder-feltet. Siden viser, hvor mange personer de kan se, og lister dem, beregnet som om ledere allerede var slået til, så du kan kontrollere, før du slår dem til. Klik på en person på listen for at se, <strong>hvorfor</strong> lederen kan se vedkommende, og hvordan det stoppes.',
            'managers_rules' => 'En leder ser kun personer i sin egen virksomhed, aldrig sig selv, og slet ikke noget, når vedkommende er stoppet. Afdelinger matches på det navn, der er skrevet på hver person, så en omdøbt afdeling holder op med at matche &mdash; siden og System &rarr; Ledere advarer om en afdelingslinje, der ikke matcher nogen. Som standard kan kun administratorer ændre ledelseslinjer; System &rarr; Ledere kan åbne den for alle, der kan redigere personer.',
            'delete_heading' => '<strong>Slet bruger</strong>',
            'delete_body' => 'Knappen <strong>Slet</strong> er <strong>FK-sikker</strong>: den afviser, hvis brugeren er anmelder på nogen sager eller har rækker i <code>users_assets</code>, og viser en tydelig besked: <em>"Kan ikke slette: denne bruger er anmelder på N sag(er). Omfordel eller luk disse sager først."</em> Revisionshistorik kan aldrig gå i stykker uden varsel.',
            'tip' => 'Alle felter i dialogboksen har browser-autoudfyldning deaktiveret (inklusive <code>autocomplete="new-password"</code> på adgangskodefeltet), så medarbejderens egne gemte loginoplysninger ikke bliver foreslået i en formular, hvis eneste formål er at oprette <em>en andens</em> post.',
            'groups_heading' => '<strong>Grupper</strong>',
            'groups_body' => 'Fanen <strong>Grupper</strong> ved siden af <strong>Personer</strong> indeholder navngivne grupper af personer &mdash; medarbejdere og brugere af selvbetjeningsportalen sammen i samme gruppe. En gruppe oprettes én gang her og bruges derefter på tværs af FreeITSM, så du kan give den adgang til en videnmappe eller tildele den et kursus uden at bygge den samme liste to gange.',
            'groups_make' => '<strong>Opret en</strong> med <strong>Tilføj</strong> på fanen Grupper: et navn og en beskrivelse, det er værd at udfylde, fordi den næste person skal kunne se, hvad gruppen bruges til.',
            'groups_add' => '<strong>Tilføj personer</strong> ved at søge efter dem &mdash; søgningen finder medarbejdere og portalbrugere sammen, så du ikke behøver at vide, hvilken slags nogen er.',
            'groups_expiry' => '<strong>Giv et medlemskab en slutdato</strong>, hvor adgangen er midlertidig. Tre teknikere på stedet i to uger tilføjes med en sidste dag og forlader gruppen af sig selv, når den passerer. Et udløbet medlemskab bliver stående på listen, markeret som udløbet, så du stadig kan se, hvem der havde adgang, og indtil hvornår.',
            'groups_uses' => '<strong>Hvad en gruppe er god til:</strong> at give adgang til en videnmappe og at tildele LMS-kurser til flere personer på én gang. Ændringer i medlemskab træder i kraft med det samme &mdash; der er intet at anvende igen bagefter.',
            'groups_admin' => '<strong>Alle med adgang til modulet Sager kan se grupperne; kun en administrator kan ændre en.</strong> At tilføje nogen til en gruppe kan også give dem adgang til en begrænset videnmappe, så det er en tildeling af adgang, ikke bare en arkivering.',
        ],
        'dash' => [
            'heading' => 'Dashboard',
            'intro' => 'Sagsdashboardet giver analyser ved et enkelt blik med tilpasselige Chart.js-widgets. Hver medarbejder har sit eget dashboard-layout, så du kan fokusere på de målepunkter, der betyder noget for din rolle &mdash; uanset om det er personlig arbejdsbyrde, teamets gennemstrømning eller SLA-overholdelse.',
            'step1' => '<strong>Åbn biblioteket</strong> &mdash; klik på Redigér dashboard for at gå ind i redigeringstilstand, og gennemse widget-biblioteket. Vælg mellem færdige widgets, eller lav din egen ved at vælge en diagramtype og den dataegenskab, der skal opsummeres.',
            'step2' => '<strong>Tilføj widgets</strong> &mdash; klik på +-knappen på en hvilken som helst widget i biblioteket for at tilføje den til dit dashboard. Den vises med det samme og begynder at vise live data fra din sagsdatabase.',
            'step3' => '<strong>Konfigurér</strong> &mdash; klik på tandhjulsikonet på en widget for at tilpasse dens titel, diagramtype (søjle, cirkel, ring, linje, stablet søjle, multi-linje), datointervalfilter, afdelingsfilter og tidsgruppering (dagligt, ugentligt, månedligt).',
            'step4' => '<strong>Arrangér</strong> &mdash; træk og slip widgets for at ændre rækkefølgen. Dit layout gemmes pr. medarbejder, så det bevares på tværs af sessioner.',
            'examples' => 'Almindelige eksempler på widgets omfatter: <strong>Sager efter status</strong> (ringdiagram, der viser åbne mod løste mod lukkede), <strong>Sager efter prioritet</strong> (søjlediagram over mængde efter alvorlighed), <strong>Ugentlig mængde</strong> (linjediagram, der følger nye sager over tid), og <strong>Medarbejdernes arbejdsbyrde</strong> (stablet søjle, der viser hver medarbejders aktive sager).',
            'tip' => 'Brug datointervalfiltre på enkelte widgets til at sammenligne aktuel præstation med tidligere perioder. En visning som "Denne måned mod sidste måned" hjælper dig f.eks. med tidligt at få øje på tendenser i sagsmængden.',
        ],
        'cal_rota' => [
            'switch_note' => 'Bruger du ikke vagtplanen? Slå den fra under <strong>System &rarr; Moduler &rarr; Tilgængelighed &rarr; Sagsfunktioner</strong> - siden, dens indstillinger og War Room-botens <em>hvem har vagt</em> forsvinder, og intet slettes.',
            'heading' => 'Kalender &amp; vagtplan',
            'intro' => 'To planlægningsværktøjer hjælper dit team med at holde styr på tingene: en sagskalender, der visualiserer arbejdsbyrden over tid, og en vagtplan til at håndtere vagter og tilkaldevagter.',
            'cal_heading' => '<strong>Kalendervisning</strong>',
            'cal_body' => 'Kalenderen plotter alle sager, du har planlagt &mdash; via <strong>Planlæg arbejde</strong>, som findes både på selve sagen og i indbakkens højreklik-menu &mdash; som en farvet blok på det planlagte tidspunkt, tegnet i dens <strong>reelle længde</strong> frem for en fast time. Røde blokke er prioritet <em>Høj</em>, grønne er <em>Lav</em>, blå er alt andet. Brug <em>I dag</em>, pilene <em>&lt;</em> / <em>&gt;</em>, og vippen <strong>Måned/Uge/Dag</strong> til at navigere.',
            'cal_scope' => '<strong>Mine eller Alles.</strong> Kalenderen åbner med dit eget planlagte arbejde, med en vippe <strong>Alle</strong> ved siden af visningsknapperne; dit valg huskes. I Alle-visningen bærer hver sag en <strong>farve for den, der ejer den</strong>, med en forklaring, der navngiver de personer, der faktisk er på skærmen, og holder du musen over en sag, kan du se, hvis den er, uden at skulle se andet sted hen. Intet er skjult for nogen &mdash; det er de samme sager, som indbakken allerede viser.',
            'cal_edit' => '<strong>Omorganisér arbejde.</strong> <strong>Træk en sag</strong> til en anden dag eller et andet tidspunkt: i månedsvisning beholder den sit tidspunkt, og i uge- og dagsvisning får den det tidspunkt, du slipper den på, afrundet til nærmeste kvarter. Dens længde ændres aldrig &mdash; at trække siger <em>start den da</em>, ikke <em>gør den længere</em>. Eller <strong>klik på en sag</strong> for at åbne den, hvor du kan ændre dato, tidspunkt, varighed og heldagsindstillingen, eller helt fjerne planlægningen. Kalenderen <strong>opdaterer sig også selv hvert par sekunder</strong>, så en kollegas nye planlægning dukker op, uden at du skal genindlæse &mdash; og den holder pause, mens du har en sag åben eller er midt i et træk.',
            'cal_month' => '<strong>Månedsvisning</strong> &mdash; det klassiske 6-rækkers gitter med en ugedagsoverskrift; hver dagcelle viser op til tre sags-mærkater med starttidspunkt, plus et link <em>+N flere</em>, der sender dig til dagsvisning for den dato. I dag er fremhævet.',
            'cal_week' => '<strong>Ugevisning</strong> &mdash; man.&ndash;søn. øverst over en lodret 24-timers tidslinje. Sager vises i deres planlagte længde, så en 15-minutters opgave og en eftermiddags-genopbygning ser forskellige ud. En heldagssag ligger som en slank bjælke øverst på sin dag i stedet for at fylde hele kolonnen. Dagens kolonne er fremhævet; ugedagsoverskriften bliver stående, mens timegitteret ruller.',
            'cal_day' => '<strong>Dagsvisning</strong> &mdash; én høj kolonne for den valgte dag med samme 24-timers tidslinje. Sager vises som større blokke, der viser <code>sagsnummer &mdash; emne</code> og starttidspunkt; klik på en for at åbne dens detaljer eller ændre, hvornår den finder sted.',
            'rota_heading' => '<strong>Vagtplan</strong>',
            'rota_body' => 'Vagtplan-siden lader teamledere og ledere planlægge medarbejdervagter hen over ugen. Definér standard arbejdstider, tildel tilkaldeperioder, og markér helligdage eller fravær, så teamet altid ved, hvem der er tilgængelig.',
            'rota_step1' => '<strong>Se vagtplansgitteret</strong> &mdash; vagtplanen viser medarbejdere langs den ene akse og dage langs den anden, med vagtblokke, der viser dækningen ved et enkelt blik.',
            'rota_step2' => '<strong>Tilføj eller redigér vagter</strong> &mdash; klik på en celle for at tildele en vagttype (f.eks. Tidlig, Sen, Nat, Tilkaldevagt). Ændringer gemmes med det samme.',
            'rota_step3' => '<strong>Planlæg fremad</strong> &mdash; naviger fremad uge for uge for at bygge vagtplanen i god tid. Det sikrer tilstrækkelig dækning i kendte travle perioder, på helligdage eller uddannelsesdage.',
            'rota_step4' => '<strong>Udfyld flere celler på én gang</strong> &mdash; <strong>højreklik</strong> på en celle, og vælg <em>Kopiér</em> for at samle vagten i den op, og højreklik derefter på en anden og <em>Indsæt</em>. For mere end én celle skal du <strong>trække hen over en blok</strong> af dem (eller ctrl-klikke celler én ad gangen) og indsætte i det hele. At holde musen over en <strong>dagoverskrift</strong> fremhæver hele den dag, og at holde musen over en <strong>medarbejders navn</strong> fremhæver hele deres uge &mdash; højreklik på hvilken som helst af dem, og indsæt i det hele. Hvor nogle af cellerne allerede har en vagt, tilbyder menuen begge muligheder i almindelige ord &mdash; <em>Indsæt i alle 7</em> og <em>Indsæt i 6 tomme celler</em> &mdash; så du vælger, før du udfører det, frem for bagefter. Overskrivning beder dig om at bekræfte og fortæller, hvor mange vagter det erstatter; at udfylde hullerne sker bare, da intet mistes. De samme menuer kan også <strong>rydde</strong> en dag, en uge eller en markering, igen efter at have fortalt dig, hvor mange vagter det fjerner.',
            'rota_step5' => '<strong>Kopiér en hel dag eller en hel uge for én person</strong> &mdash; højreklik på en <strong>dagoverskrift</strong>, og vælg <em>Kopiér</em> for at løfte hver vagt på den dag, eller en <strong>medarbejders navn</strong> for at løfte hele deres uge. At indsætte på en anden dag, eller en anden medarbejder, får det til at matche: vagter, kopien ikke havde, ryddes, så du får den dag, du kopierede, frem for en blanding af de to. En dag kan kun indsættes på en anden dag, og en medarbejder kun på en anden medarbejder &mdash; en dag er én vagt <em>pr. person</em>, og en uge er én vagt <em>pr. dag</em>, så der er ingen fornuftig måde at lægge den ene over den anden. Prøv det, og menuen siger det, og siger, hvor den kan gå i stedet.',
            'rota_step6' => '<strong>Kopiér en hel uge</strong> &mdash; <strong>Kopiér uge</strong> og <strong>Indsæt uge</strong> øverst til højre løfter hver vagt i den uge, du kigger på, og lægger dem på en anden, hvilket er den hurtigste måde at bygge en gentagende vagtplan på. At indsætte <em>erstatter</em> målugen, så bekræftelsen fortæller dig, hvor mange poster der er ved at blive fjernet. Den rører kun nogensinde de dage og personer, gitteret rent faktisk viser dig.',
            'tip' => 'Kombinér kalenderen og vagtplanen for effektiv kapacitetsplanlægning. Viser kalenderen en spids i sager hver mandag morgen, så sørg for at vagtplanen har ekstra dækning planlagt til det tidspunkt.',
        ],
        'settings' => [
            'heading' => 'Indstillinger',
            'intro' => 'Siden Indstillinger er der, hvor du konfigurerer byggestenene i dit sagsstyringssystem. Alle opslagsværdier, SLA-mål, e-mailintegration og brugerdefinerede felter administreres her.',
            'sla_callout_title' => 'SLA-styring &mdash; den fulde guide',
            'sla_callout_body' => 'Konfigurerbare indstillinger, arbejdstidskalendere, pausestatusser, overskridelsesnotifikationer, opsætning af cron-job, plus gennemregnede eksempler for teams i én tidszone og på tværs af tidszoner. Der er nok til at fortjene sin egen side.',
            'card_dept_title' => 'Afdelinger',
            'card_dept_body' => 'Opret afdelinger som IT, HR og Økonomi. Hver afdeling bliver en mappe i indbakken og et filter på dashboardet',
            'card_types_title' => 'Sagstyper',
            'card_types_body' => 'Definér de typer henvendelser, din service desk håndterer: Hændelse, Serviceanmodning, Problem, Ændring. Typer hjælper medarbejdere med at klassificere arbejdet',
            'card_type_rules_title' => 'Type til nye sager',
            'card_type_rules_body' => 'Under Sagstyper giver du hver ny sag en type, når ingen vælger en: en standard og regler før den - efter hvordan den kom ind (e-mail, portal, webchat, telefon, overvågning...), postkasse, oprindelse, afdeling, ord i emnet eller anmelderens domæne. Den første regel, der matcher, vinder; Prøv det viser, hvilken type en sag ville få',
            'card_priorities_title' => 'Prioriteter',
            'card_priorities_body' => 'Angiv prioritetsniveauer med navne, farver og sorteringsrækkefølge. Hver prioritet er knyttet til et SLA-mål for svar og løsning',
            'card_statuses_title' => 'Statusser',
            'card_statuses_body' => 'Tilpas sagens livsforløbstrin. Standardstatusser omfatter Ny, Åben, I gang, Afventer, Løst og Lukket',
            'card_categories_title' => 'Kategorier',
            'card_categories_body' => 'Gruppér sager efter teknisk område: Hardware, Software, Netværk, Adgang. Kategorier driver rapporteringsopdelinger',
            'card_sla_title' => 'SLA-mål',
            'card_sla_body' => 'Definér mål for svar- og løsningstid pr. prioritet. SLA-timere vises på sager og driver overskridelsesadvarsler',
            'card_email_title' => 'E-mailimport',
            'card_email_body' => 'Tilknyt en postkasse (Exchange, Microsoft 365) for automatisk at importere e-mails som nye sager. Svar tråd-sammenkædes tilbage i eksisterende sager',
            'card_custom_title' => 'Brugerdefinerede felter',
            'card_custom_body' => 'Tilføj dine egne felter til sager for data, din organisation skal registrere, som ikke dækkes af standardfeltsættet',
            'card_templates_title' => 'E-mailskabeloner',
            'card_templates_body' => 'Konfigurér de notifikationsskabeloner, der sendes til slutbrugere, når sager oprettes, opdateres, løses, eller til CSAT-undersøgelsen. Indsæt merge-koder som [requester_name] og [csat_link]',
            'card_checklists_title' => 'Tjeklister',
            'card_checklists_body' => 'Afgør, hvad der sker, når nogen lukker en sag, der stadig har udestående obligatoriske tjekliste-trin: <strong>advar</strong>, og registrér en intern note, der navngiver trinene og hvem der lukkede sagen, eller <strong>blokér</strong> lukningen, indtil de er udført. Håndhæves alle steder, en sag kan lukkes - bulkhandlinger, REST API\'et og workflow-automatisering inkluderet',
            'card_custom_fields_title' => 'Brugerdefinerede felter',
            'card_custom_fields_body' => 'Opret de ekstra oplysninger, en slags sag har brug for - tekst, et tal, en dato, ja / nej, en dropdown med dine egne valgmuligheder, en web- eller e-mailadresse - og knyt hvert felt til nogle sagstyper eller til dem alle. Hvert felt vælger, om det skal udfyldes <strong>når sagen oprettes</strong> (formularen Ny sag, REST API\'et og, hvis det ønskes, portalen), <strong>før den lukkes</strong> (efter reglen for obligatoriske felter) eller begge, og om <strong>anmelderen bliver spurgt</strong> om det på portalen - hvor en sagstypevælger vises, når den ændrer, hvad der spørges om. Svar vises i sagens egenskabspanel og dens historik. Når en sags type ændres, skjules de svar, den nye type ikke har, og de slettes aldrig',
            'card_mandatory_title' => 'Obligatoriske felter',
            'card_mandatory_body' => 'Afkryds de felter, der skal udfyldes, før en sag kan lukkes - kategori, løsningskode, ejer og så videre. Vælg derefter, hvad der sker, når nogen lukker en med et felt tomt: <strong>advar</strong>, <strong>advar og send e-mail</strong> til nogen, som en service delivery manager, eller <strong>nægt</strong> lukningen. En separat indstilling registrerer det på sagen som en intern note. Et felt, der er slået fra for en virksomhed, er aldrig påkrævet, og sammenlægning af sager udløser det aldrig. Håndhæves overalt, hvor en sag kan lukkes - bulk-handlinger, REST API\'et og arbejdsgangsautomatisering inklusive',
            'card_cleanup_title' => 'AI til oprydning af svar',
            'card_cleanup_body' => 'Anthropic-nøgle + model + tone til ✨ Ryd op-knappen på svareditoren. Separat nøgle fra andre AI-funktioner til detaljeret fakturering',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Sendetilstand (fra/automatisk/manuel), forsinkelse, spærring til én pr. sag, skala (stjerner eller emojis). Se afsnit 6 for hele forløbet',
            'email_heading' => '<strong>E-mailimport i detaljer</strong>',
            'email_body' => 'E-mailimportfunktionen forbinder til din delte postkasse og henter nye beskeder ind som sager. Når en slutbruger sender en e-mail til jeres supportadresse (f.eks. support@dinvirksomhed.dk), opretter FreeITSM en sag med e-mailens emne som titel og e-mailens indhold som beskrivelse. Svarer afsenderen på en notifikations-e-mail, tråd-sammenkædes svaret til den eksisterende sag i stedet for at oprette en dublet.',
            'email_step1' => '<strong>Konfigurér postkassen</strong> &mdash; gå til Indstillinger, og indtast dine Exchange- eller Microsoft 365-loginoplysninger. OAuth-godkendelse understøttes til sikre forbindelser uden adgangskode.',
            'email_step2' => '<strong>Angiv pollinginterval</strong> &mdash; vælg, hvor ofte FreeITSM tjekker postkassen for nye beskeder. Kortere intervaller betyder hurtigere oprettelse af sager.',
            'email_step3' => '<strong>Kortlæg standarder</strong> &mdash; angiv standardafdeling, -type og -prioritet for sager oprettet fra e-mail. Medarbejdere kan justere disse efter importen.',
            'email_thread_note' => '<strong>Et svar uden sagsnummer</strong> &mdash; hver e-mail, FreeITSM sender, bærer sagsnummeret, så et svar på den altid finder sin sag. Når nogen i stedet svarer på deres <em>egen</em> første e-mail (for at tilføje en vedhæftet fil, de glemte, f.eks.), er der intet nummer at finde, og som standard starter det svar en ny sag. Sæt Sager &rarr; Indstillinger &rarr; Generelt &rarr; <strong>Et svar uden sagsnummer</strong> til <strong>Kommer på den sag, samtalen hører til</strong>, så kommer det i stedet på den sag, som den første e-mail åbnede, og genåbner den, hvis den var lukket (når genåbning er slået til). Kun e-mails i samme postkasse matches.',
            'email_reply_to_note' => '<strong>Hvem Svar besvarer</strong> &mdash; som standard er svarfeltet adresseret til personen på den besked, du læser. Hvis anmelderens kolleger deltager i tråden, og du hellere altid vil svare anmelderen, sæt Sager &rarr; Indstillinger &rarr; Generelt &rarr; <strong>Svar går til</strong> til <strong>Sagens anmelder</strong>. Du kan altid ændre adressen, før du sender.',
            'email_sent_copy_note' => '<strong>En kopi af sendt post i mappen Sendt (Basic IMAP)</strong> - en Basic IMAP-postkasse sender gennem SMTP, som ikke beholder nogen kopi, så alle, der læser den samme postkasse i Thunderbird eller webmail, ville ikke se, hvad servicedesken sendte. Redigér postkassen og slå <strong>Gem en kopi af sendt post</strong> til, lige under <em>Brug IMAP-login til afsendelse</em>: hvert svar, hver skabelonmail, arbejdsgangsmail og systemmail, den sender, lægges så også i dens mappe Sendt, markeret som læst. Interne notifikationer til medarbejdere arkiveres aldrig. Lad <strong>Mappen Sendt</strong> stå tom for at bruge den mappe, din mailserver markerer som Sendt, eller skriv dens navn. Lad kontakten være slået fra, hvis din mailserver allerede arkiverer sendt post (Gmail og Microsoft 365 gør, og nogle webhoteller også) - ellers får du to kopier. <strong>Test</strong> siger, hvilken mappe kopien kom i. Hvis en kopi ikke kan gemmes, er e-mailen stadig afsendt, og årsagen står på postkassens fane <strong>Aktivitet</strong> &rarr; <strong>Udgående</strong> som <em>Kopi til mappen Sendt</em>.',
            'tip' => 'Brug e-mailskabeloner til at fastholde en professionel, ensartet tone i al kommunikation med slutbrugere. Skabeloner understøtter dynamiske pladsholdere for sagsreference, anmeldernavn, medarbejdernavn og status.',
            'closemsg_heading' => '<strong>En engangsbesked, når du lukker en sag</strong>',
            'closemsg_body' => 'Sæt <code>[ticket_closed_message]</code> et sted i en aktiv <strong>Sag lukket</strong>-skabelon, og fra da af beder det om en sætning fra medarbejderen, når en sag sættes til en lukket status - <em>&ldquo;reserveopladeren ligger på dit skrivebord&rdquo;</em>, <em>&ldquo;lukkes som aftalt i telefonen&rdquo;</em>. Uanset hvad de skriver, havner det præcis, hvor du satte pladsholderen, så du bevarer kontrollen over ordlyden omkring den. Det er ikke en indstilling, og intet gemmer det: én note, én sag, én e-mail. Skriv intet, og linjen er simpelthen ikke der - intet mellemrum, ingen løs tegnsætning.',
            'closemsg_note' => '<strong>Prompten vises kun, når pladsholderen faktisk er i skabelonen.</strong> Uden den ville alt, en medarbejder skrev, blive kasseret i stilhed, og hver supportafdeling, der ikke ønsker dette, ville få et ekstra klik ved hver eneste lukning. Så den slår sig selv til, når du konfigurerer den, og holder sig ude af vejen, når du ikke har.',
            'cat_heading' => '<strong>Kategorier, og de to felter ved siden af dem</strong>',
            'cat_body' => 'En sags <em>type</em> fortæller, hvad slags ting det er; en <em>kategori</em> fortæller, hvad den handler om. Byg listen under <strong>Indstillinger &rarr; Kategorier</strong>, sammen med de kontakter, der afgør, om nogen af det overhovedet vises på en sag.',
            'cat_card_one_title' => 'Kategori',
            'cat_card_one_body' => 'Hvad sagen blev anmeldt som, valgt når den oprettes. En sag har præcis én, så en rapport over dine kategorier altid summer til det antal sager, du faktisk havde.',
            'cat_card_close_title' => 'Kategori ved lukning',
            'cat_card_close_body' => 'Samme liste, spurgt igen når sagen afsluttes. Som regel bekræfter medarbejderen bare det oprindelige valg &mdash; den gør sin nytte på de sager, hvor det første gæt var forkert, hvilket er sådan, du finder ud af, at tolv af dine syvogtredive "printerproblemer" i virkeligheden var netværket.',
            'cat_card_res_title' => 'Løsningskode',
            'cat_card_res_body' => 'Hvordan sagen endte, frem for hvad den handlede om &mdash; "Løst fjernt", "Oplæring givet", "Ingen fejl fundet". Ti fornuftige er der fra starten, og du kan ændre dem alle.',
            'cat_rule_off' => '<strong>Alle tre starter slået fra.</strong> Byg din liste først, og slå derefter dem til, du vil bruge. Hver kan indstilles forskelligt for hver virksomhed.',
            'cat_rule_levels' => 'Kategorier kan have underkategorier op til tre niveauer dybt, og intet niveau er obligatorisk.',
            'cat_rule_type' => 'En kategori kan knyttes til én sagstype, så "Oprettelse af ny bruger" kun tilbydes på en serviceanmodning. Tilknytningen hører til topniveau-kategorien, og dens underkategorier følger den.',
            'cat_rule_typechange' => '<strong>Skift af en sags type rydder en kategori, der hørte til den gamle type</strong>, og det vises på skærmen. En kategori, der ikke er knyttet til nogen type, overlever skiftet.',
            'cat_rule_portal' => 'Sæt flueben ved <em>Slutbrugere kan vælge denne</em> for at tilbyde en kategori i selvbetjeningsportalen. Anmeldere ser en kort liste i almindeligt sprog, mens medarbejdere ser hele træet.',
            'cat_rule_retire' => 'Slå en kategori fra for at udfase den &mdash; den bliver stående på de sager, der allerede har den, og holder op med at blive tilbudt på nye. Det er næsten altid bedre end at slette, hvilket afvises, så længe noget stadig bruger den.',
            'cat_rule_report' => 'Alle tre kan vises i diagrammer på sags-dashboardet. De to kategoridiagrammer rulles op til topniveauet, og sager uden noget sat tælles som <em>Ikke kategoriseret</em> frem for at blive skjult.',
            'cat_rule_workflow' => '<strong>Kategorier i arbejdsgange:</strong> en arbejdsgang kan route sager efter kategori - en <em>Kategori</em>-betingelse virker på hver sagsudløser, og udløseren <em>En sags kategori ændres</em> fanger en sag, der kategoriseres ved triage. Som standard matcher en betingelse, der nævner en kategori, også dens underkategorier, så "Hardware" fanger "Hardware &rarr; Bærbar"; vælg <strong>Den matcher kun den kategori</strong> i <strong>Sager &rarr; Indstillinger &rarr; Kategorier &rarr; Kategorier i arbejdsgange</strong> for at lade hver arbejdsgang nævne hver underkategori, den vil have. Når en ændring af en sags type rydder dens kategori, udløses udløseren også.',
            'cat_tip' => 'Er du i tvivl om, hvor du skal starte, så lad kategorierne stå tomme, og slå kun <strong>Løsningskode</strong> til. Det er det felt, der hurtigst ændrer, hvad du gør &mdash; at en femtedel af dine sager kommer tilbage som "Oplæring givet" er et dokumentationsproblem, ikke et it-problem.',
        ],
        'tips' => [
            'heading' => 'Gode råd',
            'search_title' => 'Søg i alt',
            'search_body' => 'Søgedialogen tjekker sagsreferencer, emner, anmeldernavne og e-mailadresser. Brug den til hurtigt at finde relaterede sager, når en bruger ringer om et eksisterende problem.',
            'sla_title' => 'Hold øje med dine SLA\'er',
            'sla_body' => 'SLA-timere er synlige på hver sag i læsevinduet. Farvekodede indikatorer bliver gule, når en overskridelse nærmer sig, og røde, når målet er overskredet, så du kan prioritere derefter.',
            'reply_title' => 'Svar fra indbakken',
            'reply_body' => 'Du behøver ikke åbne dit e-mailprogram for at svare en slutbruger. Brug knappen Svar i læsevinduet til at sende en besked direkte. Den tråd-sammenkædes automatisk til sagen.',
            'reply_to_title' => 'Hvem Svar går til',
            'reply_to_body' => 'Svar er adresseret til personen på den besked, du læser. Hvis du hellere vil have, at det altid går til sagens anmelder, så ændr <strong>Svar går til</strong> i Sager &rarr; Indstillinger &rarr; Generelt. Uanset hvad kan du ændre adressen eller tilføje personer i Cc, før du sender.',
            'trail_title' => 'Brug aktivitetssporet',
            'trail_body' => 'Før du arbejder på en sag, så rul gennem dens aktivitetsspor. Tidligere medarbejderes noter, e-mails og feltændringer giver dig den fulde kontekst, så du undgår at bede brugeren om at gentage oplysninger.',
            'dash_title' => 'Dashboard til ledere',
            'dash_body' => 'Byg et dashboard med widgets for SLA-overholdelse, gennemsnitlig løsningstid og sager pr. afdeling. Del det på teammøder for at drive løbende forbedring.',
            'rota_title' => 'Planlæg med vagtplanen',
            'rota_body' => 'Udfyld vagtplanen mindst to uger frem. Kombineret med kalendervisningen hjælper det dig med at finde huller i dækningen, før de bliver et problem for svartiderne.',
            'drag_title' => 'Træk for at triagere',
            'drag_body' => 'Træk sager fra listen ind på mapper for at opdatere dem uden at åbne. Afdelings- og status-undermapper opdaterer begge dele på én gang. Fjedrende udfoldning gør indlejrede statusser tilgængelige midt i et træk.',
            'dbl_title' => 'Dobbeltklik for fuldskærm',
            'dbl_body' => 'Enkeltklik viser en sag i læsevinduet; dobbeltklik åbner den i fuldskærmstilstand til fokuseret arbejde. Klik på maksimér-ikonet ved siden af emnet for at skifte tilbage.',
            'rightclick_title' => 'Højreklik for hurtige handlinger',
            'rightclick_body' => 'Højreklik på en sag for ét-klik-ændringer af status, prioritet eller tildelt medarbejder samt kæd CMDB og registrér tid, alt sammen uden at forlade den sag, du er ved at læse.',
            'ai_title' => 'Lad AI rydde op i dit svar',
            'ai_body' => 'Skriv et groft udkast (eller bare punkter), og klik på <strong>✨ Ryd op</strong> &mdash; Claude omskriver det til en ordentlig e-mail med hilsen, rettet grammatik og afslutning. Fortryd-link vises i 30 sekunder.',
            'feedback_title' => 'Bed om feedback',
            'feedback_body' => 'Slå CSAT til under <strong>Indstillinger &rarr; CSAT</strong> for automatisk at bede anmeldere om en vurdering, når deres sager lukkes. Tendenser pr. medarbejder findes på <code>tickets/csat/</code> &mdash; guld til udviklingssamtaler.',
            'precreate_title' => 'Opret slutbrugere på forhånd',
            'precreate_body' => 'Navigationsknappen <strong>Brugere</strong> lader dig tilføje en bruger, før vedkommende har brug for at oprette en sag &mdash; lad adgangskoden stå tom, så kan de selv overtage kontoen via selvbetjeningsportalen.',
        ],
        'companies' => [
            'heading' => 'Virksomheder &amp; e-mailfordeling',
            'intro' => 'Når din installation betjener mere end én virksomhed (f.eks. en it-leverandør, der understøtter flere kunder), holdes hver virksomheds sager adskilt. Dette afsnit forklarer, hvordan en indgående e-mail finder frem til den rette virksomhed.',
            'switcher_body' => 'En <strong>virksomhedsvælger</strong> vises i headeren. Den bestemmer, hvilken virksomhed du arbejder i &mdash; sagslisten, mapperne og antallene viser alle kun den virksomhed, og enhver sag, du opretter, arkiveres til den. Medarbejdere med adgang til flere virksomheder kan skifte mellem dem; den aktuelle vises altid, så du aldrig svarer i den forkerte sammenhæng. Administrér selve virksomhederne under <strong>System &rarr; Virksomheder</strong>.',
            'mailboxes_heading' => 'Enhver postkasse er af én af to slags &mdash; det er dette, der afgør fordelingen:',
            'card_pinned_title' => 'Fastgjort postkasse',
            'card_pinned_body' => 'Dedikeret til én virksomhed (f.eks. en kundes egen <code>itsupport@</code>). <strong>Al</strong> dens post arkiveres til den virksomhed &mdash; afsenderen ignoreres &mdash; og svar sendes ud igen fra den, så kunden oplever sin egen service desk fra ende til anden.',
            'card_shared_title' => 'Delt indtagspostkasse',
            'card_shared_body' => 'Én adresse, der betjener mange virksomheder (f.eks. en leverandørs enkelte <code>support@leverandoeren.com</code>). Den kan ikke kende virksomheden ud fra adressen alene, så den regner det ud fra <strong>hvem der har sendt e-mailen</strong>. Den anbefalede opsætning for en leverandør med mange kunder.',
            'routing_heading' => 'Sådan vælger en delt indtagspostkasse virksomhed',
            'routing_body' => 'For hver indgående e-mail prøves disse i rækkefølge, og det første match vinder:',
            'flow_reply' => 'Svar på en sag',
            'flow_sender' => 'Kendt afsender',
            'flow_domain' => 'Kendt domæne',
            'flow_triage' => 'Triage',
            'rule_reply' => '<strong>1. Svar på en eksisterende sag</strong> &mdash; genkendt på sit referencenummer, e-mailen knyttes til den sag og beholder dens virksomhed.',
            'rule_sender' => '<strong>2. En bestemt afsenderadresse</strong> knyttet til en virksomhed (f.eks. <code>jane@gmail.com</code> &rarr; Acme) &mdash; den virksomhed. Tjekkes før domænet, så det virker selv for personlige/webmail-adresser.',
            'rule_domain' => '<strong>3. Afsenderens domæne</strong> knyttet til en virksomhed (f.eks. alle <code>@acme.com</code> &rarr; Acme) &mdash; den virksomhed.',
            'rule_triage' => '<strong>4. Intet match</strong> &mdash; e-mailen går til <strong>triage</strong>-køen i stedet for at gå tabt (se nedenfor).',
            'keys_heading' => 'Domæner &amp; specifikke afsendere (angives pr. virksomhed under System &rarr; Virksomheder)',
            'keys_body' => 'Det er disse nøgler, en delt indtagspostkasse matcher på. Hver virksomhed angiver de e-maildomæner, den ejer, og eventuelt individuelle afsenderadresser.',
            'card_domains_title' => 'E-maildomæner',
            'card_domains_body' => 'De domæner, en virksomhed ejer (acme.com, acme.co.uk). Enhver afsender på et registreret domæne fordeles til den virksomhed. Et domæne tilhører kun én virksomhed.',
            'card_senders_title' => 'Specifikke afsendere',
            'card_senders_body' => 'Individuelle adresser knyttet til en virksomhed, tjekkes før domænet. Brug det til en freelancer eller en lille kunde, der sender fra en personlig adresse.',
            'card_public_title' => 'Offentlige udbydere',
            'card_public_body' => 'Gmail, Outlook, Yahoo og lignende kan ikke kortlægges som et domæne (mange urelaterede personer deler dem) &mdash; kortlæg i stedet den præcise adresse som en specifik afsender.',
            'triage_heading' => 'Triage-køen &mdash; sikkerhedsnettet',
            'triage_body' => 'Når en e-mail til en delt indtagspostkasse ikke matcher nogen virksomhed, havner den i <strong>Triage</strong> (nås fra virksomhedsvælgeren, med et live antal) i stedet for at gå tabt. Hvert element viser afsenderen, domænet, emnet og hvilken postkasse det ankom til. Arkivér det til en virksomhed i ét trin:',
            'triage_create' => 'Vælg en eksisterende virksomhed, eller opret en ny på stedet.',
            'triage_assign' => 'For et normalt domæne kan du valgfrit <strong>fordele det domæne</strong> til virksomheden; for en offentlig/webmail-adresse kan du valgfrit <strong>altid arkivere den afsender</strong> dér.',
            'triage_sweep' => 'Begge valg <em>fejer</em>: det flytter også alle andre e-mails i kø fra det domæne eller den adresse og fordeler automatisk fremtidig post &mdash; så du kun sorterer en given afsender én gang.',
            'triage_tip' => 'Intet går nogensinde tabt. Umatchet post venter i triage, indtil nogen arkiverer den; en ikke-arkiveret sag vises i mellemtiden stadig under standardvirksomheden.',
            'test_heading' => 'Test din fordeling, før du går i drift',
            'test_body' => 'Under <strong>System &rarr; Test af e-mailfordeling</strong> kan du foregive, at en e-mail er ankommet &mdash; vælg en postkasse, indtast en afsenderadresse &mdash; og se præcis, hvilken virksomhed den nye sag ville havne hos (eller om den ville gå til triage), og hvilken regel der afgjorde det. Det opretter intet; det læser blot dine indstillinger.',
            'settings_heading' => 'Indstillinger: delt som standard, tilpasset hvor det betyder noget',
            'settings_body' => 'Nogle af disse indstillinger kan <strong>tilpasses pr. virksomhed</strong>; andre forbliver bevidst delt. Hvor en indstilling er en simpel liste af muligheder &mdash; som <strong>sagstyper</strong> og <strong>oprindelser</strong> &mdash; skifter du ind i en virksomheds kontekst, ser du de delte standarder (hver med et øjenikon til at skjule dem, den ikke bruger) plus dem, den selv har tilføjet. Du kan ikke skjule eller slette en mulighed, mens åbne sager stadig bruger den, og de delte standarder redigeres selv fra MSP\'en/standardvirksomheden.',
            'settings_custom_title' => 'Tilpasset pr. virksomhed',
            'settings_custom_body' => 'Sagstyper &amp; oprindelser (nu), samt kategorier, SLA\'er &amp; åbningstider (kommer) &mdash; ting der reelt varierer fra kunde til kunde.',
            'settings_global_title' => 'Delt på tværs af alle virksomheder',
            'settings_global_body' => 'Statusser og prioriteter forbliver de samme overalt, så rapportering og SLA\'er på tværs af virksomheder forbliver konsistente; det samme gælder jeres teams, vagtplan og postkasser &mdash; jeres egen drift, ikke en kundes.',
            'allview_heading' => '<strong>Ét samlet overblik på tværs af alle virksomheder</strong>',
            'allview_body' => 'Virksomhedsvælgeren i headeren har en indstilling kaldet <strong>Alle virksomheder</strong>. Alle sager, du har adgang til at se, vises i én liste, hvor hver række bærer den virksomhed, den tilhører &mdash; nyttigt, når du understøtter flere enheder og vil have ét samlet overblik over dagen uden at miste styr på, hvad der hører til hvem.',
            'allview_card_scope_title' => 'Det giver ingen ny adgang',
            'allview_card_scope_body' => '"Alle" betyder alle de virksomheder, du allerede kunne tilgå én ad gangen. En medarbejder, der understøtter to af jeres tre enheder, ser præcis de to, og en medarbejder med én virksomhed ser en visning af den ene virksomhed.',
            'allview_card_props_title' => 'Hver enhed forbliver adskilt',
            'allview_card_props_body' => 'Åbn en sag, og dens type, oprindelse, kategori og løsningsliste er dem, der tilhører <em>den</em> virksomhed &mdash; så en kategori, én enhed har, og en anden ikke har, aldrig kan blive anvendt på den forkerte sag.',
            'allview_card_new_title' => 'Nye sager spørger, hvilken virksomhed',
            'allview_card_new_body' => 'Der er ingen enkelt aktiv virksomhed at antage, og valget afgør sagsnummeret, den postkasse svar sendes fra, og den SLA, der gælder. Typelisten udfyldes, når du har valgt.',
            'allview_rule_chip' => 'En sag, der er ankommet via e-mail eller portalen uden endnu at være routet, mærkes <strong>Ikke routet</strong> frem for at blive vist under Standard, så den skiller sig ud til triage.',
            'allview_rule_reply' => 'Svar sendes stadig fra den postkasse, sagen ankom til &mdash; det følger sagen, ikke visningen, så et samlet overblik aldrig kan sende fra den forkerte adresse.',
            'allview_rule_knowledge' => '<strong>Spørg AI</strong> søger i alle virksomheder, du kan se, mens den samlede visning er slået til, i stedet for kun én. Artikler delt med alle virksomheder er inkluderet under alle omstændigheder.',
            'allview_rule_trash' => '<strong>At tømme papirkurven går aldrig på tværs af virksomheder.</strong> Det gælder altid kun den ene virksomhed, du sidst valgte, fordi "slet alt i papirkurven" på tværs af flere enheder på én gang ikke er, hvad nogen mener med det.',
            'allview_rule_other' => 'Kun sagslisten udvides. Aktiver, ændringer, opgaver og CMDB\'en viser stadig én virksomhed ad gangen &mdash; skift til den virksomhed for at arbejde i dem.',
            'privacy_heading' => 'Hver virksomheds sager forbliver private',
            'privacy_body' => 'Når du arbejder i en virksomheds kontekst, ser du kun <strong>den</strong> virksomheds sager &mdash; i listen, i søgning, på dashboards og på enhver sag, du åbner (inklusive dens e-mails, vedhæftede filer, noter og historik). En medarbejder kan kun tilgå en sag, hvis vedkommende er givet adgang til dens virksomhed (du vælger hver medarbejders virksomheder under System &rarr; Medarbejdere, eller giver et helt team adgang under System &rarr; Teams), så der er ingen vej til at ende i en anden kundes data. Denne adskillelse håndhæves overalt bag kulisserne, ikke bare skjult i visningen. På en installation med én virksomhed sker det automatisk og usynligt &mdash; der er kun én virksomhed, så alt tilhører den ganske enkelt.',
            'tip' => 'På en installation med én virksomhed vises intet af dette &mdash; der er én virksomhed, hver sag tilhører den, og der er ingen vælger eller triage. Disse funktioner slås først til, når en anden virksomhed findes.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'SLA-styring',
        'back_link' => '&larr; Tilbage til guiden til Sager',
        'sidebar_title' => 'SLA-guide',
        'hero_title' => 'SLA-styring',
        'hero_sub' => 'Svar- og løsningsmål der tager hensyn til åbningstider, med overskridelsesnotifikationer pr. afdeling',
        'nav' => [
            'overview' => 'Overblik',
            'building_blocks' => 'Byggesten',
            'behaviour_settings' => 'Adfærdsindstillinger',
            'breach_notifications' => 'Overskridelsesnotifikationer',
            'cron_setup' => 'Opsætning af cron-job',
            'worked_examples' => 'Gennemregnede eksempler',
            'troubleshooting' => 'Fejlfinding',
        ],
        'overview' => [
            'heading' => 'Overblik',
            'sub' => 'Hvad SLA\'er er, hvorfor de er vigtige, og hvordan FreeITSM\'s motor fungerer på et overordnet niveau.',
            'p1' => 'En Service Level Agreement (SLA) er et løfte om, hvor hurtigt jeres team vil svare på og løse en sag. FreeITSM følger to ure pr. sag: <strong>svar</strong> (tiden fra sagen oprettes, til første medarbejderhandling) og <strong>løsning</strong> (tiden fra sagen oprettes, til sagen lukkes). Begge mål angives pr. prioritet &mdash; så en P1 kan have 30 minutter til svar og 4 timer til løsning, mens en P4 kan have 8 arbejdstimer og 5 arbejdsdage.',
            'switch_note' => 'Bruger du ikke SLA\'er? Slå SLA fra under <strong>System &rarr; Moduler &rarr; Tilgængelighed &rarr; Sagsfunktioner</strong>: ure, overskridelsesadvarsler og SLA-udløsere i arbejdsgange stopper, mens forretningskalenderne forbliver til webchattens åbningstider. Slås det til igen, spørger den, om de advarsler, der blev misset, mens det var slået fra, skal sendes eller springes over.',
            'p2' => 'FreeITSM\'s SLA-motor har fire designvalg, det er værd at forstå:',
            'choice_business' => '<strong>Åbningstider, ikke uret på væggen.</strong> En P2 rejst kl. 16:30 med et svar-mål på 1 time bliver ikke overskredet kl. 17:30, hvis kontoret lukker kl. 17. Uret genoptages kl. 9 den næste arbejdsdag. Det er branchestandarden og den eneste rimelige model, når medarbejdere tager hjem om aftenen.',
            'choice_pause' => '<strong>Kan sættes på pause.</strong> Når en sag er i en status markeret "Sæt SLA på pause" (som f.eks. <em>Afventer svar</em> eller <em>Sat i bero</em>), stopper uret. Det genoptages, når sagen flyttes tilbage til en arbejdsstatus.',
            'choice_compute' => '<strong>Beregnes ved læsning, gemmes ikke.</strong> Motoren genberegner SLA-status ud fra sagens revisionslog, hver gang du ser den. Der findes ingen gemte tællere, der kan glide ud af synkronisering. Ændrer du senere åbningstiderne i en arbejdstidskalender, genberegnes SLA\'en for alle historiske sager ud fra de nye tider, næste gang de vises.',
            'choice_cutoff' => '<strong>Ikrafttrædelsesdato.</strong> En admin-styret dato "Håndhæv SLA\'er fra" betyder, at eksisterende sager i jeres system ikke pludselig bliver overskredet med tilbagevirkende kraft, når I slår SLA\'er til. Kun sager oprettet på eller efter ikrafttrædelsesdatoen følges.',
            'tip' => 'Er du ny til ITIL: svartid handler om anerkendelse (nogen har taget sagen); løsningstid handler om afslutning (brugerens problem er løst). De to ure kører uafhængigt af hinanden og har forskellige mål.',
        ],
        'blocks' => [
            'heading' => 'De fire byggesten',
            'sub' => 'Konfigurér disse fire ting, og SLA-sporing er i drift. Alt andet er valgfri finpudsning.',
            'cal_heading' => '1. Arbejdstidskalendere',
            'cal_intro' => 'En kalender definerer, hvornår jeres service desk har åbent. Hver kalender har:',
            'cal_tz' => '<strong>Tidszone</strong> &mdash; en IANA-tidszoneidentifikator (f.eks. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Sommertidsskift håndteres automatisk.',
            'cal_hours' => '<strong>Ugentlige åbningstider</strong> &mdash; én række pr. ugedag med et afkrydsningsfelt for åbent og start-/sluttidspunkt. Nye kalendere sættes som standard til man.-fre. 09:00-17:00, lør./søn. lukket. En række uden markeringen Åben betyder, at der er lukket den dag.',
            'cal_holidays' => '<strong>Helligdage</strong> &mdash; dato + valgfrit navn. Helligdage tilsidesætter det ugentlige mønster (der er lukket, selv om det falder på en mandag).',
            'cal_default' => '<strong>Standardmarkering</strong> &mdash; præcis én kalender er standard. Nye prioriteter arver den, medmindre du angiver andet.',
            'cal_outro' => 'Du kan oprette lige så mange kalendere, du har brug for &mdash; én pr. kontor, én pr. team, én til VIP-kunder med udvidede åbningstider. De deles af SLA-mål og overskridelsesmotoren.',
            'prio_heading' => '2. Prioriteter med SLA-mål',
            'prio_intro' => 'På fanen Prioriteter (eller via tabellen SLA-mål på fanen SLA) kan hver prioritet have:',
            'prio_response' => '<strong>Svar-mål (minutter)</strong> &mdash; hvor lang tid der må gå til første medarbejderhandling.',
            'prio_resolution' => '<strong>Løsningsmål (minutter)</strong> &mdash; hvor lang tid der må gå, til sagen er lukket.',
            'prio_calendar' => '<strong>Kalender</strong> &mdash; hvilken arbejdstidskalender denne prioritets ur kører imod. Lad stå tom for at bruge standardkalenderen.',
            'prio_outro' => 'Lades begge målfelter tomme, slås SLA-sporing helt fra for den prioritet &mdash; nyttigt til en prioritet som "Informativ" eller "Backlog", hvor der ikke er noget tidspres.',
            'pause_heading' => '3. Statusser der sætter SLA på pause',
            'pause_intro' => 'På fanen Statusser findes en dedikeret kolonne "Sæt SLA på pause". Markér enhver status, der repræsenterer, at sagen er blokeret af noget uden for teamets kontrol. Standardkandidater er:',
            'pause_awaiting' => '<strong>Afventer svar</strong> &mdash; kunden skylder os oplysninger. Næsten universelt accepteret som en rimelig pause.',
            'pause_vendor' => '<strong>Sat i bero (leverandør)</strong> &mdash; venter på support fra Microsoft eller en tredjepart.',
            'pause_change' => '<strong>Sat i bero (ændringsvindue)</strong> &mdash; planlagt til et fremtidigt vedligeholdelsesvindue.',
            'pause_parts' => '<strong>Sat i bero (reservedele)</strong> &mdash; venter på levering af hardware.',
            'pause_warn' => 'En generisk "Sat i bero"-status kan misbruges som en SLA-udvej, når en sag er svær, eller medarbejderen har travlt. Har jeres team disciplinen til det, er det fint. Hvis ikke, kan I overveje at erstatte den med de mere specifikke varianter ovenfor, eller stole på dashboardet <strong>Vagttårn</strong>, som markerer sager sat i bero i over 24 timer med en gul advarsel.',
            'cutoff_heading' => '4. Ikrafttrædelsesdato (<code>Håndhæv SLA\'er fra</code>)',
            'cutoff_p1' => 'Den enkeltvis vigtigste globale indstilling. Før du angiver en dato/tid her, er SLA-sporing helt slået fra &mdash; ingen ure kører, ingen mærkater vises i indbakken, ingen overskridelses-e-mails sendes. Sætter du den til en dato/tid i fortiden, slås SLA\'er til med tilbagevirkende kraft fra det tidspunkt. Sætter du den til en dato/tid i fremtiden, planlægges en tænding.',
            'cutoff_p2' => 'De fleste teams sætter denne til "nu", når de først slår SLA\'er til &mdash; eksisterende sager beholder deres tilstand fra før SLA\'er, nye sager fra det tidspunkt følges.',
        ],
        'behaviour' => [
            'heading' => 'Adfærdsindstillinger',
            'sub' => 'Disse styrer, hvordan motoren reagerer på grænsetilfælde. Standardværdierne er fornuftige &mdash; du behøver kun at ændre dem, hvis du har en bestemt præference.',
            'prio_heading' => 'Når prioriteten ændres undervejs',
            'prio_intro' => 'Hvis en P3-sag opgraderes til P1 halvvejs (fordi problemet viser sig at være større end først antaget), er der tre rimelige adfærdsformer:',
            'prio_forward' => '<strong>Overfør (standard)</strong> &mdash; bevar de optjente arbejdsminutter og omregn blot målet. Har sagen brugt 2t af sit 8t P3-mål, har den nu 2t brugt mod sit 1t P1-mål &mdash; hvilket betyder, at den allerede er overskredet. Kan argumenteres for at være korrekt: sagen VAR en P1 hele tiden, teamet vidste bare ikke det.',
            'prio_recompute' => '<strong>Genberegn</strong> &mdash; nulstil uret, og anvend det nye mål med tilbagevirkende kraft fra sagens oprettelse. En ren genberegning.',
            'prio_reset' => '<strong>Nulstil</strong> &mdash; start det nye ur helt forfra fra det øjeblik, prioriteten blev ændret. Mest overbærende for teamet, men kunder kan føle sig snydt, hvis en sag med høj prioritet pludselig får et helt nyt langt ur.',
            'reopen_heading' => 'Når en lukket sag genåbnes',
            'reopen_intro' => 'Genåbnes en sag (brugeren svarer efter lukning):',
            'reopen_reset' => '<strong>Nulstil (standard)</strong> &mdash; start et helt nyt svar- og løsningsur fra genåbningstidspunktet. Behandl genåbningen, som om det reelt er en ny sag.',
            'reopen_continue' => '<strong>Fortsæt</strong> &mdash; genoptag ud fra den forløbne tid ved lukning. De oprindelige SLA-mål fortsætter med at gælde.',
            'first_heading' => 'Definition af første svar',
            'first_intro' => 'Hvad tæller som "første svar" &mdash; det øjeblik, der stopper svaruret?',
            'first_either' => '<strong>Enten (standard)</strong> &mdash; den første medarbejderhandling af enhver art: en udgående e-mail, en statusændring, en tildeling.',
            'first_status' => '<strong>Statusændring</strong> &mdash; kun en statusændring væk fra standarden tæller. Strengere &mdash; medarbejderen skal rent faktisk have arbejdet på sagen, ikke bare klikket på den.',
            'first_email' => '<strong>Udgående e-mail</strong> &mdash; kun et e-mailsvar til anmelderen tæller. Strengest &mdash; kunden skal have hørt fra os.',
            'warn_heading' => 'Advarselsgrænse i procent',
            'warn_body' => 'Hvor langt gennem SLA-målet der er nået, før indikatoren skifter fra grøn til gul. Standard er 80 % &mdash; så et svar-mål på 60 minutter viser gul efter 48 minutters forløbet tid. Styrer også overskridelsesnotifikationer udløst af advarslen.',
        ],
        'breach' => [
            'heading' => 'Overskridelsesnotifikationer',
            'sub' => 'Konfigurerbare e-mailregler pr. afdeling, der udløses, når SLA\'er nærmer sig en overskridelse (advarsel), eller rent faktisk overskrides.',
            'intro' => 'Hver regel har fire dimensioner, alle uafhængige:',
            'scope_heading' => '1. Omfang',
            'scope_body' => 'Enten <strong>Standard</strong> (reglen gælder for sager i enhver afdeling) eller en <strong>specifik afdeling</strong>. Afgørelse: en afdelingsspecifik regel vinder over standardreglen for sager i den afdeling. Uden en standardregel får afdelinger uden en specifik regel ingen notifikationer.',
            'trigger_heading' => '2. Udløser',
            'trigger_body' => 'Enten <strong>Advarsel</strong> (sagen har krydset advarselsgrænsen &mdash; potentiel overskridelse) eller <strong>Overskridelse</strong> (sagen har overskredet sit mål &mdash; faktisk overskridelse). Hver er sin egen regel, så I kan notificere forskellige personer for hver.',
            'target_heading' => '3. Mål',
            'target_body' => 'Hvilket ur der skal overvåges &mdash; <strong>Svar</strong>, <strong>Løsning</strong> eller <strong>Begge</strong>.',
            'recip_heading' => '4. Modtagere',
            'recip_intro' => 'En hvilken som helst kombination af:',
            'recip_assignee' => '<strong>Sagens tildelte medarbejder</strong> &mdash; den medarbejder, der aktuelt ejer sagen. Springes over, hvis ikke tildelt.',
            'recip_teams' => '<strong>Medlemmer af sagens afdelingsteams</strong> &mdash; alle medarbejdere i ethvert team knyttet til sagens afdeling. Dækker hele køen uden at skulle vedligeholde en distributionsliste.',
            'recip_specific' => '<strong>En bestemt medarbejder</strong> &mdash; mønsteret "SLA-ansvarlig"/"servicechef", hvor det er en navngiven person, ikke en rolle.',
            'recip_custom' => '<strong>Brugerdefinerede e-mailadresser</strong> &mdash; kommasepareret fritekst. Nyttigt til delte postkasser (<code>sla-alerts@company.com</code>), Slack/Teams-e-mailbroer eller distributionslister.',
            'tip' => 'Hver sag sender højst én e-mail pr. (mål, udløser) &mdash; cron-jobbet fører logbog over, hvad der allerede er sendt, i tabellen <code>sla_notifications_sent</code>. Så en advarsel sendes én gang, en overskridelse sendes én gang, og det er det &mdash; ingen spam-løkker.',
            'warn' => '<strong>Ingen regler = ingen e-mails.</strong> Selv hvis hver eneste sag i systemet overskrides, sker der intet, før du tilføjer mindst én regel. Start med et Standard-omfang med en Advarsel + Overskridelse-parring for at dække alt.',
        ],
        'cron' => [
            'heading' => 'Opsætning af cron-jobbet',
            'sub' => 'Overskridelsestjekket skal køre efter en plan. Hvert 5. minut er det sødeste punkt.',
            'p1' => 'De SLA-indikatorer, der er synlige i brugerfladen (mærkater i indbakken, paneler i læsevinduet), beregnes i farten, når en side indlæses. Men overskridelses-e-mails kan kun sendes, hvis <em>noget</em> proaktivt tjekker sager, selv når ingen kigger på dem. Det noget er en planlagt opgave &mdash; på Windows Jobplanlægning, på Linux cron.',
            'p2' => 'Scriptet er <code>cron/sla_breach_check.php</code> i FreeITSM\'s installationsmappe. Det kan kaldes på to måder:',
            'cli_heading' => 'A. Kommandolinje (anbefales på en server, du selv styrer)',
            'cli_note' => 'Ingen godkendelse kræves &mdash; filsystemets rettigheder afgør allerede, hvem der kan køre det.',
            'http_heading' => 'B. HTTP (til delt hosting eller eksterne planlæggere)',
            'http_note' => 'Token\'et genereres automatisk ved første installation og gemmes i <code>system_settings</code> under nøglen <code>sla_cron_token</code> (32 hex-tegn, ~128 bits entropi). Det er krypteret ved lagring, så læser du rækken direkte, får du <code>ENC:…</code> i stedet for selve token\'et. Find dit med:',
            'win_heading' => 'Windows Jobplanlægning',
            'win_intro' => 'Åbn Jobplanlægning (<code>taskschd.msc</code>), og opret en ny opgave med disse indstillinger:',
            'tbl_field' => 'Felt',
            'tbl_value' => 'Værdi',
            'win_r1_k' => 'Navn',
            'win_r1_v' => 'FreeITSM &mdash; SLA-overskridelsestjek',
            'win_r2_k' => 'Kør, uanset om brugeren er logget på eller ej',
            'win_r2_v' => 'Sæt flueben her',
            'win_r3_k' => 'Udløser',
            'win_r3_v' => 'Dagligt, gentag hver 1. dag, gentag hvert 5. minut i 1 dag',
            'win_r4_k' => 'Handling',
            'win_r4_v' => 'Start et program',
            'win_r5_k' => 'Program/script',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Tilføj argumenter',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Start i',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'Tilføj én linje til jeres crontab (<code>crontab -e</code>):',
            'sec_heading' => 'Sikkerhed &mdash; hvad beskytter HTTP-endpointet',
            'sec_intro' => 'Tre lag, alle håndhævet automatisk:',
            'sec_token' => '<strong>1. Delt hemmelig token</strong> &mdash; 128-bit tilfældig pr. installation, sammenlignet med konstant-tids-matching for at forhindre timing-angreb.',
            'sec_lockout' => '<strong>2. Spærring pr. IP ved fejlet godkendelse</strong> &mdash; mere end 10 forkerte token-forsøg fra samme IP inden for den seneste time udløser en 1-times 429-spærring. Afværger brute force-forsøg uden behov for fail2ban.',
            'sec_interval' => '<strong>3. Minimumsinterval mellem gennemførte kørsler</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (standard 30 s). Selv en forespørgsel med gyldigt token får et 429-svar, hvis den ankommer hurtigere end dette efter den seneste gennemførte kørsel. Afværger utilsigtet dobbeltplanlægning og løbske løkker.',
            'log_heading' => 'Aktivitetslog',
            'log_body' => 'Hvert kald (godkendt eller afvist) logges i tabellen <code>sla_cron_runs</code> med tidspunkt, resultat, antal og klientens IP. Se de sidste 20 kørsler i panelet <strong>Cron-aktivitet</strong> nederst på fanen SLA-indstillinger &mdash; nyttigt til at verificere, at planen kører, og til at revidere eventuelle fejlede godkendelsesforsøg. Rækker beskæres automatisk efter <code>sla_cron_log_retention_days</code> (standard 30) dage, så tabellen forbliver lille.',
        ],
        'examples' => [
            'heading' => 'Gennemregnede eksempler',
            'sub' => 'Fra det simple tilfælde med én tidszone til det trickere tilfælde på tværs af tidszoner, hvor "fair" skal defineres.',
            'ex1_heading' => 'Eksempel 1: Sag rejst i Storbritannien, service desk i Storbritannien',
            'ex1_title' => 'Det simple tilfælde',
            'ex1_tag' => 'én tidszone',
            'ex1_setup' => '<strong>Opsætning:</strong> Én arbejdstidskalender kaldet <em>UK-kontor</em> med tidszonen <code>Europe/London</code>, man.-fre. 09:00-17:00, ingen helligdage. Prioriteten P2 har et svar-mål på 1 time og et løsningsmål på 4 timer, begge kørende mod kalenderen <em>UK-kontor</em>.',
            'ex1_scenario' => '<strong>Scenarie:</strong> En bruger rejser en P2-sag kl. <strong>16:30 UK-tid om onsdagen</strong>.',
            'ex1_timeline' => 'Ons 16:30 UK &mdash; <strong>sagen oprettes</strong>, svaruret starter.
Ons 17:00 UK &mdash; kontoret lukker, uret sættes på pause (30 min brugt af 60 min-målet).
Tors 09:00 UK &mdash; kontoret åbner, uret genoptages.
Tors 09:30 UK &mdash; medarbejderen svarer. Svar-SLA\'en overholdes lige på kanten (60 min brugt, 60 min-mål).',
            'ex1_outro' => 'Havde medarbejderen ikke svaret før <strong>torsdag kl. 10:00 UK</strong>, ville svaret være <strong>overskredet med 30 minutter</strong> (90 min brugt mod 60 min-målet &mdash; 30 fra onsdag aften, 60 fra torsdag morgen). Det 1-times ur tikker kun i åbningstiden, men en sag rejst sidst på dagen æder stadig det meste af sit budget natten over, når kontoret genåbner &mdash; det er let for en medarbejder, der møder ind kl. 09:00, at antage, at de har den fulde time, når der i virkeligheden kun er 30 minutter tilbage.',
            'ex2_heading' => 'Eksempel 2: Sag rejst i Storbritannien, service desk i Estland',
            'ex2_title' => 'Tilfældet på tværs af tidszoner',
            'ex2_tag' => '3 måder at definere "fair" på',
            'ex2_setup' => '<strong>Opsætning:</strong> Britiske kunder (<code>Europe/London</code>, GMT/BST), service desk i Estland (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 timer foran Storbritannien</strong>). Begge desks arbejder nominelt 09:00-17:00 lokal tid.',
            'ex2_scenario' => '<strong>Scenarie:</strong> En britisk kunde rejser en P2-sag kl. <strong>16:30 UK-tid en fredag</strong> (= 18:30 estisk tid, efter estisk lukketid). Den næste mulighed for en estisk medarbejder til at arbejde med den er mandag kl. 09:00 estisk tid (= 07:00 UK-tid). Svar-målet er 1 time.',
            'ex2_question' => 'Hvad bør SLA\'en sige? Der er tre forsvarlige svar, hver fair på sin egen måde. I vælger, hvilken kalender der knyttes til prioriteten, ud fra hvad jeres servicekontrakt lover.',
            'optA_label' => 'Mulighed A &mdash; kundecentreret',
            'optA_p1' => '<strong>Sæt prioriteten til at bruge en kalender med <em>britiske</em> åbningstider.</strong> Uret tikker mod britisk 09:00-17:00, uanset hvor medarbejderen befinder sig.',
            'optA_p2' => 'I scenariet ovenfor, sag rejst kl. 16:30 UK fredag: uret kører 16:30&ndash;17:00 UK fredag (30 min brugt), sættes på pause natten over + weekend, genoptages man. 09:00 UK. Svarer en estisk medarbejder kl. 10:00 estisk tid mandag (= 08:00 UK-tid), er den britiske kalender stadig på pause (kontoret i UK åbner kl. 09:00 UK-tid), så der tikker ikke flere minutter &mdash; forbruget forbliver på 30 min. <strong>SLA overholdt med 30 min margin</strong>. Ethvert svar efter 09:30 UK-tid (= 11:30 estisk tid) ville være en overskridelse.',
            'optA_p3' => '<em>Fair over for:</em> kunden. Deres oplevelse matcher deres arbejdsdag.<br><em>Kompromis:</em> estiske medarbejdere forventes at være tilgængelige 09:00-17:00 UK-tid (= 11:00-19:00 estisk tid), hvilket forlænger deres arbejdsdag med 2 timer.',
            'optB_label' => 'Mulighed B &mdash; medarbejdercentreret',
            'optB_p1' => '<strong>Sæt prioriteten til at bruge en kalender med <em>estiske</em> åbningstider.</strong> Uret tikker mod estisk 09:00-17:00.',
            'optB_p2' => 'Samme scenarie: sag rejst kl. 18:30 estisk tid fredag (efter lukketid), uret på pause hele weekenden, begynder at tikke man. kl. 09:00 estisk tid (= 07:00 UK-tid). Svarer medarbejderen kl. 09:30 estisk tid mandag (= 07:30 UK-tid), har svar-SLA\'en brugt 30 min af 60 min-målet &mdash; <strong>overholdt med 30 min margin</strong>. Den britiske kunde rejste sagen kl. 16:30 UK-tid fredag og fik svar kl. 07:30 UK-tid mandag &mdash; deres ventetid på uret var langt længere, end SLA\'en antyder.',
            'optB_p3' => '<em>Fair over for:</em> medarbejderne. De arbejder normale timer.<br><em>Kompromis:</em> britiske kunder kan føle, at SLA\'en "lyver", hvis en sag fra fredag eftermiddag først anerkendes mandag morgen estisk tid, mens rapporten siger, at svar-SLA\'en var 1 time. Sørg for, at jeres servicekontrakt tydeligt angiver, at SLA\'en kører mod service deskens åbningstider.',
            'optC_label' => 'Mulighed C &mdash; overlapvindue (strengest)',
            'optC_p1' => '<strong>Sæt prioriteten til at bruge en kalender, der kun dækker de timer, hvor begge desks har åbent.</strong> UK 09:00-17:00 overlapper med Estland 09:00-17:00 (= UK 07:00-15:00) i <strong>vinduet UK 09:00-15:00</strong> &mdash; 6 timer pr. arbejdsdag.',
            'optC_p2' => 'Samme scenarie: sag rejst kl. 16:30 UK-tid fredag (uden for overlappet, da overlappet lukker kl. 15:00 UK-tid), uret på pause over weekenden, genoptages man. kl. 09:00 UK-tid (= 11:00 estisk tid, det øjeblik overlappet genåbner). Svarer den estiske medarbejder kl. 11:30 estisk tid (= 09:30 UK-tid), har svar-SLA\'en brugt 30 min af 60 min-målet &mdash; <strong>overholdt med 30 min margin</strong>. Svaret skete inden for overlapvinduet, så det tæller med det samme.',
            'optC_p3' => '<em>Fair over for:</em> begge sider &mdash; SLA\'en tikker kun i de timer, hvor desken faktisk kunne fremme sagen OG kunden sidder ved sit skrivebord for at modtage et svar.<br><em>Kompromis:</em> et kortere dagligt vindue betyder længere tid på uret for at nå ambitiøse mål. Et løsningsmål på 4 timer strækker sig over 1,5 dags overlap, hvor det med en normal 8-timers kalender ville være klaret inden for én dag.',
            'choose_tip' => '<strong>Sådan vælger I:</strong> Se på jeres servicekontrakt. Står der "svar inden for 1 time efter modtagelse" &mdash; det er mulighed A (kundens ur). Står der "svar inden for 1 arbejdstime" &mdash; det er typisk mulighed B (den desk, der er på arbejde). Står der "inden for 1 time efter gensidig tilgængelighed" &mdash; det er mulighed C. Er der ingen kontrakt, så spørg teamet: vil I føle pres uden for estisk arbejdstid (mulighed A), eller vil I have, at britiske kunder af og til føler sig overset (mulighed B)?',
            'ex3_heading' => 'Eksempel 3: Pause af uret under ventetid hos leverandør',
            'ex3_title' => 'Sådan fungerer pausestatusser i praksis',
            'ex3_tag' => 'pause af uret',
            'ex3_setup' => '<strong>Opsætning:</strong> Prioriteten P3 med et løsningsmål på 8 arbejdstimer, UK-kalender, statussen "Afventer leverandør" markeret <em>Sæt SLA på pause</em>.',
            'ex3_scenario' => '<strong>Scenarie:</strong> Sagen rejses man. kl. 09:00 UK-tid. Medarbejderen eskalerer til Microsoft man. kl. 11:00 UK-tid og flytter sagen til "Afventer leverandør". Microsoft svarer ons. kl. 14:00 UK-tid. Medarbejderen implementerer rettelsen og lukker sagen tors. kl. 10:00 UK-tid.',
            'ex3_timeline' => 'Man. 09:00 &mdash; sagen oprettes, løsningsuret kører.
Man. 11:00 &mdash; flyttet til "Afventer leverandør", <strong>uret sættes på pause</strong> (2t brugt).
Ons. 14:00 &mdash; flyttet tilbage til "I gang", <strong>uret genoptages</strong>.
Ons. 17:00 &mdash; kontoret lukker (5t brugt i alt).
Tors. 09:00 &mdash; kontoret åbner.
Tors. 10:00 &mdash; sagen lukkes (6t brugt i alt). <strong>SLA overholdt</strong> mod 8t-målet.',
            'ex3_outro' => 'Forløbet tid på uret: ~3 dage. Forløbet SLA-tid: 6 arbejdstimer. Uden markeringen for pausestatus ville SLA\'en have talt alle 2 dages leverandørventetid + åbningstid med, i alt ~18 arbejdstimer &mdash; langt over en overskridelse.',
        ],
        'trouble' => [
            'heading' => 'Fejlfinding',
            'sub' => 'Almindelige problemer, og hvad du skal tjekke.',
            'col_symptom' => 'Symptom',
            'col_cause' => 'Sandsynlig årsag',
            'r1_s' => 'Ingen SLA-mærkater vises i indbakken',
            'r1_c' => '<code>Håndhæv SLA\'er fra</code> er tom, prioriteten har ingen mål angivet, eller sagen ligger før ikrafttrædelsesdatoen.',
            'r2_s' => 'SLA vises som overskredet, men medarbejderen svarede inden for målet',
            'r2_c' => 'Tjek prioritetens ændringshistorik &mdash; hvis prioriteten blev opgraderet undervejs, og adfærden er sat til "Overfør" (standard), overføres den optjente tid.',
            'r3_s' => 'Overskridelsesnotifikationer sendes ikke',
            'r3_c' => '(1) Ingen regler konfigureret. (2) Cron-jobbet ikke planlagt. (3) Regler konfigureret, men modtagere kan ikke findes (ingen tildelt medarbejder, afdelingsteams har ingen medlemmer med e-mail). Tjek panelet Cron-aktivitet for en oversigt pr. kørsel.',
            'r4_s' => 'Cron kører, men melder "ingen matchende regel"',
            'r4_c' => 'Tilføj mindst én regel med Standard-omfang, så alle afdelinger er dækket.',
            'r5_s' => 'Vagttårn viser "N sager sat i bero i over 24 timer"',
            'r5_c' => 'Sager sidder fast i en pausestatus for SLA. Enten har nogen bevidst parkeret dem og glemt dem, eller også bruger nogen Sat i bero som en SLA-udvej. Klik ind på hver enkelt, og fremskrid dem eller fjern pausestatussen.',
            'r6_s' => 'HTTP-cron returnerer 403',
            'r6_c' => 'Token\'et i URL\'en matcher ikke. Slå det op med <code>SELECT setting_value FROM system_settings WHERE setting_key = \'sla_cron_token\'</code>.',
